INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1000, '亚龙湾国家旅游度假区', '三亚市吉阳区亚龙湾路1号', '亚龙湾位于三亚市东南端，是三亚最具标志性的海滨浴场，也是国家AAAA级旅游景区。亚龙湾因传说海中有一条巨龙而得名，湾长7.5公里，沙质细腻柔软如棉，被誉为“东方夏威夷”“天下第一湾”。', 'attraction', '三亚', '免费开放（部分景点如亚龙湾玫瑰谷60元/人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1001, '天涯海角游览区', '三亚市天涯区天涯海角风景区', '天涯海角位于三亚市西南端，是三亚最著名的标志性景观，也是国家AAAA级旅游景区。天涯海角因古代贬官流放至此，视为天之涯、海之角而得名，距今已有1000多年人文历史，素有“天涯地角”“海枯石烂”之美誉。', 'attraction', '三亚', '81元/人（成人），40元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1002, '南山文化旅游区', '三亚市崖州区崖州湾路1号（南山文化旅游区内）', '南山文化旅游区位于三亚市西南端，是集佛教文化、热带海洋风光、民俗文化于一体的综合性文化旅游区，也是国家AAAA级旅游景区。南山文化旅游区始建于1995年，占地面积约50公顷，是三亚最具文化内涵的旅游区之一。', 'attraction', '三亚', '145元/人（成人），73元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1003, '鹿回头风景区', '三亚市吉阳区鹿岭路1号（鹿回头山顶）', '鹿回头位于三亚市西南端鹿回头山顶，是三亚最具标志性的城市观景台，也是国家AAA级旅游景区。鹿回头因黎族民间传说“鹿回头”而得名，相传一位黎族青年猎人追逐一只美丽花鹿至南海之滨，花鹿回头化身美丽黎族少女，两人因此相爱，结为夫妻，故得名“鹿回头”。', 'attraction', '三亚', '45元/人（成人），23元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1004, '大东海旅游区', '三亚市吉阳区榆亚路1号（大东海湾畔）', '大东海位于三亚市东郊，是离三亚市中心最近的海滨浴场，也是国家AAA级旅游景区。大东海因传说海中有一头大东海龟而得名，湾长2.5公里，沙质细腻，海水清澈，是理想的城市海滨浴场。', 'attraction', '三亚', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1005, '三亚海鲜（第一市场）', '三亚市天涯区新建街（第一市场内）', '第一市场是三亚最有名的海鲜聚集地，游客可以在市场内选购新鲜海鲜，然后拿到附近的加工店进行烹饪，经济实惠，是体验三亚海鲜文化的绝佳去处。', 'restaurant', '三亚', '150-300元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1006, '三亚海鲜（春园海鲜广场）', '三亚市吉阳区凤凰路（春园海鲜广场）', '春园海鲜广场是三亚最有名的海鲜聚集地之一，沿途有数十家海鲜加工店，海鲜均来自南海当日捕捞，新鲜味美，是品尝三亚海鲜的绝佳去处。', 'restaurant', '三亚', '100-200元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1007, '三亚海南鸡饭', '三亚市天涯区解放路（多家海南鸡饭店）', '海南鸡饭是三亚最具代表性的特色美食，鸡肉鲜嫩，饭粒吸满鸡油，鲜香味美，是到三亚必尝的特色美食。', 'restaurant', '三亚', '60-120元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1008, '三亚椰子鸡', '三亚市吉阳区迎宾路（多家椰子鸡店）', '椰子鸡是三亚最具代表性的家常菜，用椰青和鸡肉炖煮而成，汤头清甜，肉质鲜嫩，是体验三亚热带风味的绝佳去处。', 'restaurant', '三亚', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1009, '三亚小吃聚集区（解放路步行街、鸿港市场）', '三亚市天涯区解放路步行街、鸿港市场', '解放路步行街和鸿港市场是三亚最著名的小吃聚集区，汇聚了三亚各种特色小吃和海南美食，是品尝三亚美食、体验三亚慢生活的绝佳去处。', 'restaurant', '三亚', '40-80元*', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1010, '三亚亚特兰蒂斯酒店', '三亚市吉阳区海棠北路36号', '超五星级海滨度假酒店，位于海棠湾畔，拥有大型水族箱和 Waterpark，设施豪华，服务一流，是亲子度假和高端旅游的理想选择。', 'hotel', '三亚', '2000-8000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1011, '三亚湾假日酒店', '三亚市天涯区三亚湾路88号', '五星级海滨度假酒店，位于三亚湾畔，部分客房可俯瞰三亚湾美景，设施豪华，服务优质，是商务出行和高端旅游的理想选择。', 'hotel', '三亚', '1000-2500元/晚*', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1012, '如家酒店（三亚解放路店）', '三亚市天涯区解放路128号*', '经济型连锁酒店，位于解放路核心地段，购物交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '三亚', '200-400元/晚*', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1013, '亚龙湾度假酒店聚集区', '三亚市吉阳区亚龙湾路（多家五星级度假酒店）*', '亚龙湾是三亚五星级度假酒店最集中的区域，各大国际品牌酒店均在此设有度假村，是海滨度假的理想选择。', 'hotel', '三亚', '800-5000元/晚*', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1014, '三亚湾民宿聚集区', '三亚市天涯区三亚湾路（多家民宿）*', '三亚湾有大量的家庭式民宿，价格实惠，主人热情好客，提供家常海鲜餐食，是体验三亚本地生活的经济之选。', 'hotel', '三亚', '150-600元/晚*', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1015, '外滩', '上海市黄浦区中山东一路（沿黄浦江畔）', '外滩位于上海市黄浦区黄浦江畔，全长约1.5公里，是上海最具标志性的景观之一，也是中国历史文化街区。外滩南起延安东路，北至外白渡桥，沿线矗立着52幢风格迥异的古典复兴大楼，素有"万国建筑博览群"之美誉，是上海百年沧桑的见证。', 'attraction', '上海', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1016, '上海迪士尼乐园', '上海市浦东新区川沙新镇黄赵路310号', '上海迪士尼乐园位于上海市浦东新区川沙新镇，是中国大陆第一个、亚洲第三个、全球第六个迪士尼主题乐园，于2016年6月16日正式开园。乐园占地面积约1.16平方公里，包括七大主题园区：米奇大街、奇想花园、梦幻世界、探险岛、宝藏湾、明日世界、玩具总动员。', 'attraction', '上海', '475-799元/人（根据季节和日期浮动）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1017, '豫园（豫园旅游区）', '上海市黄浦区豫园老街279号', '豫园位于上海市黄浦区，是上海著名的古典园林，始建于明嘉靖三十八年（1559年），万历五年（1577年）竣工，至今已有460多年历史。豫园占地面积约2公顷，是江南古典园林的代表作之一，与苏州古典园林齐名，被誉为"城市山林""奇秀甲于东南""东南名园冠"。', 'attraction', '上海', '40元/人（豫园古典园林），城隍庙区域免费', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1018, '陆家嘴金融贸易区（东方明珠、上海中心大厦）', '上海市浦东新区陆家嘴环路（东方明珠：世纪大道1号）', '陆家嘴金融贸易区位于上海市浦东新区，黄浦江东南岸，与外滩隔江相望，是上海最具现代感的城市天际线，也是中国最具影响力的金融中心之一。陆家嘴汇聚了东方明珠、上海中心大厦、上海环球金融中心、金茂大厦等摩天大楼，构成了壮观的城市景观。', 'attraction', '上海', '东方明珠A票220元/人，上海中心大厦观光厅220元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1019, '南京路步行街', '上海市黄浦区南京东路（河南中路至西藏中路段）', '南京路步行街位于上海市黄浦区，西起西藏中路，东至河南中路，全长约1033米，是上海最繁华的商业街之一，也是世界闻名的商业街区，素有"中华商业第一街"之美誉。南京路始建于1851年，至今已有170多年历史，是上海商业发展的缩影和见证。', 'attraction', '上海', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1020, '南翔馒头店（豫园店）', '上海市黄浦区豫园老街85号', '南翔馒头店始创于1900年，是上海最著名的小笼包专营店，豫园店是总店，已有120多年历史。小笼包皮薄馅大，汤汁鲜美，是上海最具代表性的特色小吃之一。', 'restaurant', '上海', '60-100元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1021, '老正兴菜馆（福州路店）', '上海市黄浦区福州路343号', '老正兴菜馆始创于1862年（清同治元年），是上海最老的宁波风味菜馆，也是中国餐饮百强企业。以宁波菜和上海本帮菜为主，口味鲜美，做工精细，是体验上海本帮菜的首选餐厅。', 'restaurant', '上海', '150-250元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1022, '上海老饭店（福佑路店）', '上海市黄浦区福佑路242号', '上海老饭店始创于1875年，是上海本帮菜的代表性餐厅，以传统上海菜为主，口味浓郁，做工讲究，是品尝正宗上海本帮菜的绝佳去处。', 'restaurant', '上海', '120-200元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1023, '小杨生煎（南京东路店）', '上海市黄浦区南京东路636号', '小杨生煎是上海最有名的生煎包连锁店，创立于1994年，以生煎包皮脆底酥、汤汁饱满、肉馅鲜美而著称，是上海最受欢迎的平价小吃之一。', 'restaurant', '上海', '30-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1024, '沈大成（南京东路店）', '上海市黄浦区南京东路636号（近浙江中路）', '沈大成始创于1875年，是上海老字号点心店，以各类中式点心著称，条头糕软糯香甜，双酿团口感丰富，是品尝上海传统点心的绝佳去处。', 'restaurant', '上海', '30-60元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1025, '上海外滩华尔道夫酒店', '上海市黄浦区中山东一路2号', '超五星级豪华酒店，位于外滩核心地段，由两栋建筑组成，新建的现代塔楼与修复的历史建筑完美融合，服务一流，设施豪华，是体验外滩风情的首选下榻之处。', 'hotel', '上海', '2500-5000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1026, '上海浦东丽思卡尔顿酒店', '上海市浦东新区陆家嘴世纪大道8号上海国金中心', '超五星级豪华酒店，位于陆家嘴核心地段，客房可俯瞰浦江两岸美景，服务细致入微，设施一流，是商务出行和高端旅游的理想选择。', 'hotel', '上海', '2000-4000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1027, '如家酒店（上海南京东路地铁站店）', '上海市黄浦区南京东路480号', '经济型连锁酒店，位于南京东路步行街核心地段，购物交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '上海', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1028, '上海豫园万丽酒店', '上海市黄浦区豫园老街159号', '四星级精品酒店，位于豫园旅游区内，建筑风格融合了海派文化和江南园林元素，充满文化气息，是体验上海传统文化的理想住宿选择。', 'hotel', '上海', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1029, '上海国际青年旅舍（田子坊店）', '上海市黄浦区泰康路210弄5号（田子坊内）', '经济型青年旅舍，位于田子坊创意产业区内，充满艺术气息，价格实惠，是背包客和年轻游客的理想选择。', 'hotel', '上海', '100-300元/晚（床位/经济房）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1030, '中山陵景区', '南京市玄武区石象路7号（钟山风景名胜区内）', '中山陵位于南京市玄武区钟山第二峰小茅山之南坡，是中国近代民主革命先行者孙中山先生的陵寝，也是南京最具标志性的景观之一，国家AAAAA级旅游景区。中山陵于1926年春动工，1929年夏建成，占地面积约8万平方米，主要建筑有牌坊、墓道、陵门、碑亭、祭堂和墓室等，排列在一条中轴线上，体现了中国传统建筑的风格。', 'attraction', '南京', '免费开放（需提前预约），美龄宫30元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1031, '明孝陵景区', '南京市玄武区紫金山南麓独龙阜玩珠峰下', '明孝陵位于南京市玄武区紫金山南麓，是明太祖朱元璋和马皇后的合葬陵墓，始建于明洪武十四年（1381年），历时25年建成，是中国规模最大的帝王陵寝之一，也是世界文化遗产、国家AAAAA级旅游景区。明孝陵占地面积约170万平方米，陵园纵深2.62公里，围绕孝陵红墙周长约40公里，堪称“明清皇家第一陵”。', 'attraction', '南京', '70元/人（旺季），60元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1032, '夫子庙', '南京市秦淮区贡院街152号（夫子庙景区）', '夫子庙-秦淮风光带位于南京市秦淮区，是以夫子庙为中心，秦淮河为纽带，包括瞻园、夫子庙、白鹭洲公园、中华门、江南贡院、李香君故居、王导谢安纪念馆等多处历史文化遗迹在内的综合性旅游区，被誉为“十里秦淮，六朝金粉”，国家AAAAA级旅游景区。', 'attraction', '南京', '夫子庙免费开放，科举博物馆40元/人，秦淮画舫白天60元/人、夜晚80元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1033, '总统府', '南京市玄武区长江路292号', '南京总统府位于南京市玄武区长江路292号，是中国近代史遗址博物馆，也是南京最重要的历史文化景点之一，国家AAAA级旅游景区。总统府建筑群占地面积约9万平方米，迄今已有600多年的历史，历经明初汉王府、清前期两江总督署、清后期江宁织造署、太平天国天王府、清季两江总督署、中华民国总统府、南京国民政府等多个历史时期，堪称“中国近代史的缩影”。', 'attraction', '南京', '40元/人（成人），20元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1034, '南京大屠杀遇难同胞纪念馆', '南京市建邺区水西门大街418号', '南京大屠杀遇难同胞纪念馆位于南京市建邺区水西门大街418号，是为纪念1937年南京大屠杀中的遇难同胞而建的纪念馆，也是国家一级博物馆、全国爱国主义教育示范基地。纪念馆占地面积约7.4万平方米，建筑面积约2.5万平方米，于1985年落成开放，后经多次扩建，现已成为包括集会广场、遗址悼念、史料陈列、和平公园等多个功能区的综合性纪念馆。', 'attraction', '南京', '免费开放（需提前预约）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1035, '南京大牌档（德基广场店）', '南京市玄武区中山路18号德基广场7楼', '南京大牌档创立于1994年，是南京最具代表性的餐饮品牌之一，以金陵菜和秦淮小吃为主，餐厅装修为民国时期南京街市风格，是体验南京饮食文化和民国风情的绝佳去处。', 'restaurant', '南京', '80-120元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1036, '回味鸭血粉丝汤（户部街店）', '南京市秦淮区户部街32号', '回味鸭血粉丝汤是南京最有名的鸭血粉丝汤连锁店，创立已有20多年，以鸭血鲜嫩、粉丝滑爽、汤头鲜美而著称，是南京人最喜爱的早餐和夜宵之一。', 'restaurant', '南京', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1037, '绿柳居（太平南路店）', '南京市秦淮区太平南路248号', '绿柳居始创于1912年，是南京最著名的素菜馆，以素菜仿荤、做工精细、口味鲜美而著称，是体验南京素食文化的绝佳去处。', 'restaurant', '南京', '30-60元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1038, '蒋有记锅贴（老门东店）', '南京市秦淮区老门东箍桶巷21号', '蒋有记锅贴是南京老字号小吃店，始创于1940年代，以牛肉锅贴外脆里嫩、汁水饱满而著称，是南京最具代表性的特色小吃之一。', 'restaurant', '南京', '25-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1039, '夫子庙小吃聚集区', '南京市秦淮区贡院街（夫子庙景区内）', '夫子庙小吃聚集区是南京最著名的小吃街区，汇聚了南京各种特色小吃和老字号餐厅，是品尝南京特色美食、体验秦淮风情的绝佳去处。', 'restaurant', '南京', '50-100元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1040, '南京金陵饭店', '南京市鼓楼区汉中路2号', '五星级豪华酒店，位于市中心，曾是南京第一高楼，装修典雅豪华，设施一流，服务优质，是商务出行和高端旅游的理想选择。', 'hotel', '南京', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1041, '南京香格里拉大酒店', '南京市鼓楼区中央路329号', '五星级豪华酒店，位于鼓楼核心地段，装修典雅豪华，设施一流，服务细致入微，是南京市标志性豪华酒店之一。', 'hotel', '南京', '700-1500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1042, '如家酒店（南京夫子庙店）', '南京市秦淮区平江府路158号', '经济型连锁酒店，位于夫子庙景区附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '南京', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1043, '南京老门东民宿聚集区', '南京市秦淮区老门东内（多家民宿）', '古色古香的民宿聚集区，位于老门东内，建筑风格古朴典雅，充满历史韵味，是体验南京古城文化、感受秦淮风情的理想住宿选择。', 'hotel', '南京', '200-500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1044, '南京钟山宾馆', '南京市玄武区中山东路307号', '四星级园林式酒店，位于钟山风景区附近，环境清幽，空气清新，客房分布在花园般的环境中，是游览钟山景区后理想的休息之处。', 'hotel', '南京', '400-800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1045, '鼓浪屿风景名胜区', '厦门市思明区鼓浪屿（需从轮渡码头乘船）', '鼓浪屿位于厦门市思明区，是厦门湾中的一座小岛，与世界文化遗产，国家AAAAA级旅游景区。鼓浪屿因岛西南端海蚀洞受浪潮冲击，声如擂鼓，明朝时雅化为“鼓浪屿”，距今已有近500年历史，素有“海上花园”“音乐之岛”之美誉。', 'attraction', '厦门', '鼓浪屿免费开放，部分景点联票100元/人（含日光岩、皓月园、菽庄花园、风琴博物馆、刻字博物馆）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1046, '南普陀寺', '厦门市思明区思明南路515号', '南普陀寺位于厦门市思明区五老峰下，是一座历史悠久的佛教寺院，也是闽南佛教文化的中心，始建于唐末五代（约907-960年），距今已有1000多年历史，因供奉观音菩萨，又在普陀山以南，故名“南普陀寺”。', 'attraction', '厦门', '免费开放（需提前预约）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1047, '厦门大学（思明校区）', '厦门市思明区思明南路422号', '厦门大学位于厦门市思明区五老峰下，依山傍海，风景秀丽，是中国最美的大学之一，被誉为“山海花园大学”。厦门大学始建于1921年，由著名爱国华侨陈嘉庚先生创办，是中国近代教育史上第一所华侨创办的大学，距今已有100多年历史。', 'attraction', '厦门', '免费开放（需提前预约，工作日限300人/天，节假日限500人/天）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1048, '环岛路', '厦门市思明区环岛路（全长约43公里）', '环岛路位于厦门市思明区东南沿海，全长约43公里，是厦门最著名的海滨景观大道，也是厦门国际马拉松赛的主赛道，素有“世界上最美的马拉松赛道”之美誉。环岛路依海而建，路宽景美，沿途设有多个观景台和休息区，是骑行、慢跑、散步的理想去处。', 'attraction', '厦门', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1049, '曾厝垵', '厦门市思明区环岛路曾厝垵片区', '曾厝垵位于厦门市思明区环岛路旁，是一个始建于明代的渔村，距今已有600多年历史，素有“中国最文艺渔村”之美誉。曾厝垵在2000年代开始转型，大量文艺青年在此开设民宿、咖啡馆、手工艺品店等，逐渐发展成为了厦门最具文艺气息的旅游街区。', 'attraction', '厦门', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1050, '沙茶面（乌糖沙茶面）', '厦门市思明区民族路54号', '沙茶面是厦门最具代表性的特色小吃，用沙茶酱、花生酱、辣椒油等多种调料烹制汤头，搭配海鲜、猪杂、蔬菜等，味道鲜美独特，是厦门人最喜爱的早餐和夜宵之一。', 'restaurant', '厦门', '30-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1051, '海蛎煎（莲欢海蛎煎）', '厦门市思明区局口街局口横巷33号', '海蛎煎是厦门最具代表性的特色小吃，用海蛎、鸡蛋、番薯粉等煎制而成，外酥里嫩，鲜香味美，是到厦门必尝的特色美食。', 'restaurant', '厦门', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1052, '土笋冻（西门外土笋冻）', '厦门市思明区西门外（多家小摊）', '土笋冻是厦门最具特色的平民小吃，用海沙虫（星虫）熬煮冷却后凝固而成，口感Q弹，味道鲜美，是厦门人最喜爱的夜宵之一。', 'restaurant', '厦门', '15-30元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1053, '厦门烧肉粽（1980烧肉粽总店）', '厦门市思明区中山路353号', '烧肉粽是厦门最具代表性的特色小吃，用糯米包裹猪肉、香菇、栗子等馅料，外叶用竹叶包裹，蒸熟后香气四溢，是厦门人最喜爱的早餐之一。', 'restaurant', '厦门', '25-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1054, '姜母鸭（厦门姜母鸭总店）', '厦门市思明区大同路17号', '姜母鸭是厦门最具代表性的滋补美食，用番鸭、老姜、麻油、米酒等炖煮而成，味道醇厚，滋补养身，是厦门人最喜爱的家常菜之一。', 'restaurant', '厦门', '60-100元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1055, '厦门海港英迪格酒店', '厦门市思明区鹭江道16号', '五星级精品酒店，位于鹭江道，紧邻鼓浪屿轮渡码头，部分客房可俯瞰鼓浪屿和厦门港美景，设计时尚，服务优质，是商务出行和高端旅游的理想选择。', 'hotel', '厦门', '1000-2500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1056, '厦门喜来登酒店', '厦门市思明区嘉禾路386-1号', '五星级商务酒店，位于嘉禾路核心地段，装修典雅豪华，设施一流，服务细致入微，是厦门市标志性豪华酒店之一。', 'hotel', '厦门', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1057, '如家酒店（厦门中山路店）', '厦门市思明区中山路步行街268号', '经济型连锁酒店，位于中山路步行街核心地段，购物交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '厦门', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1058, '鼓浪屿民宿聚集区', '厦门市思明区鼓浪屿岛上（多家民宿）', '鼓浪屿上有大量的家庭式民宿，多为历史建筑改建而成，风格各异，充满文艺气息，是体验鼓浪屿慢生活的理想住宿选择。', 'hotel', '厦门', '200-800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1059, '曾厝垵民宿聚集区', '厦门市思明区曾厝垵片区内（多家民宿）', '曾厝垵内有大量的文艺民宿，价格实惠，主人热情好客，提供家常菜和旅游咨询服务，是体验厦门文艺慢生活的经济之选。', 'hotel', '厦门', '150-500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1060, '包公祠（包孝肃公祠）', '合肥市包河区芜湖路72号（包公文化园内）', '包公祠位于合肥市包河区包公文化园内，是为纪念北宋名臣包拯（包公）而建的祠堂，也是合肥最具标志性的历史文化景点，国家AAAA级旅游景区。包公祠始建于明弘治元年（1488年），历经各代修葺扩建，形成了包括包公祠、包公墓、清风阁、浮庄、九狮广场等在内的包公文化园。', 'attraction', '合肥', '50元/人（成人），25元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1061, '三河古镇', '合肥市肥西县三河镇三河路1号', '三河古镇位于合肥市肥西县南端，距合肥市区约40公里，是中国历史文化名镇，也是国家AAAA级旅游景区。三河古镇因丰乐河、杭埠河、小南河三水交汇而得名，距今已有2500多年历史，素有"皖中水乡""春秋古镇"之美誉。', 'attraction', '合肥', '免费开放（部分景点收费，联票80元/人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1062, '巢湖风景名胜区', '合肥市巢湖市巢湖路1号（巢湖之滨）', '巢湖位于合肥市南部，是中国五大淡水湖之一，也是合肥最具代表性的自然景观，素有"皖中明珠""八百里湖天"之美誉。巢湖东西长55公里，南北宽22公里，水域面积约750平方公里，湖岸线长约180公里，是合肥的"母亲湖"。', 'attraction', '合肥', '免费开放（部分景点收费）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1063, '徽园', '合肥市蜀山区繁华大道276号', '徽园位于合肥市蜀山区，是安徽省最大的仿明清建筑群，也是国家AAAA级旅游景区。徽园始建于1999年，是为庆祝新中国成立50周年而建，占地面积约20公顷，集中展示了安徽17个地市的风貌特色和历史文化，素有"不到徽园，不知安徽"之美誉。', 'attraction', '合肥', '20元/人（成人），10元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1064, '安徽博物院', '合肥市蜀山区怀宁路268号', '安徽博物院位于合肥市蜀山区，是安徽省最大的综合性博物馆，也是国家一级博物馆。博物院占地面积约6.2万平方米，建筑面积约4.1万平方米，收藏有各类文物和标本40余万件，其中珍贵文物约10万余件，是了解安徽历史文化的重要窗口。', 'attraction', '合肥', '免费开放（需提前预约）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1065, '庐州烤鸭店（宿州路总店）', '合肥市庐阳区宿州路106号', '庐州烤鸭店始创于清光绪年间，是合肥最著名的老字号餐厅，以庐州烤鸭为代表作，烤鸭皮脆肉嫩，鸭油汤包汤汁鲜美，是体验合肥本帮菜的首选餐厅。', 'restaurant', '合肥', '40-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1066, '刘鸿盛（人民广场总店）', '合肥市庐阳区人民广场东侧', '刘鸿盛始创于清光绪年间，是合肥最著名的小吃店，以鸭油汤包和鸭油烧饼著称，汤包皮薄馅大，汤汁鲜美，是合肥最具代表性的特色小吃之一。', 'restaurant', '合肥', '30-60元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1067, '三河米饺（三河古镇内多家店）', '合肥市肥西县三河古镇内（多家小吃店）', '三河米饺是三河古镇的传统小吃，用米粉制成饺皮，以五花肉、豆腐、马蹄等为馅，油炸而成，外皮酥脆，内馅鲜美，是三河古镇最具代表性的特色小吃。', 'restaurant', '合肥', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1068, '巢湖银鱼（巢湖畔多家餐厅）', '合肥市巢湖市巢湖路（多家海鲜餐厅）', '巢湖银鱼是巢湖最具代表性的水产品，肉质鲜嫩，味道清甜，用银鱼蒸蛋、银鱼炒蛋等都是巢湖周边餐厅的招牌菜，是品尝巢湖鲜味的绝佳去处。', 'restaurant', '合肥', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1069, '合肥小龙虾（宁国路小龙虾一条街）', '合肥市包河区宁国路（小龙虾一条街）', '宁国路小龙虾一条街是合肥最著名的小龙虾聚集地，沿途有数十家小龙虾专营店，麻辣鲜香，是合肥人最喜爱的夜宵之一。', 'restaurant', '合肥', '60-120元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1070, '合肥华润万象城君悦酒店', '合肥市蜀山区潜山路1111号', '五星级豪华酒店，位于万象城商圈核心地段，装修典雅豪华，设施一流，服务优质，是商务出行和高端旅游的理想选择。', 'hotel', '合肥', '1000-2500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1071, '合肥元一希尔顿酒店', '合肥市瑶海区胜利路198号', '五星级豪华酒店，位于胜利路商务区，紧邻元一时代广场，设施豪华，服务一流，是合肥市标志性豪华酒店之一。', 'hotel', '合肥', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1072, '如家酒店（合肥包公祠店）', '合肥市包河区芜湖路128号', '经济型连锁酒店，位于包公祠附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '合肥', '180-320元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1073, '三河古镇民宿聚集区', '合肥市肥西县三河古镇内（多家民宿）', '古色古香的古镇民宿，位于三河古镇内，建筑风格古朴典雅，充满水乡韵味，是体验古镇慢生活的理想住宿选择。', 'hotel', '合肥', '150-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1074, '巢湖畔度假酒店', '合肥市巢湖市巢湖路（多家度假酒店）', '度假型酒店，位于巢湖畔，环境清幽，空气清新，是游览巢湖后理想的休息之处。', 'hotel', '合肥', '300-800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1075, '大召寺（银佛寺）', '呼和浩特市玉泉区大召前街48号', '大召寺位于呼和浩特市玉泉区，是呼和浩特最早兴建的藏传佛教寺院，始建于明万历七年（1579年），由蒙古土默特部首领阿勒坦汗主持修建，是呼和浩特藏传佛教文化的中心和象征。大召寺因寺内供奉有一尊纯银制作的释迦牟尼像，又称"银佛寺"，银佛高2.55米，重约3万两白银，工艺精湛，栩栩如生，是大召寺的镇寺之宝。', 'attraction', '呼和浩特', '35元/人（成人），20元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1076, '昭君墓（青冢）', '呼和浩特市玉泉区昭君路南端', '昭君墓位于呼和浩特市玉泉区，是汉代王昭君的陵墓，始建于西汉时期，距今已有2000多年历史，是呼和浩特最重要的历史文化遗迹之一，也是中华民族民族团结的象征。王昭君名嫱，西汉南郡（今湖北省兴山县）人，元帝时入宫，竟宁元年（公元前33年）自愿请行出嫁匈奴呼韩邪单于，为汉匈两族和平友好做出了巨大贡献，被后人传颂至今。', 'attraction', '呼和浩特', '65元/人（成人），35元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1077, '席力图召', '呼和浩特市玉泉区石头巷北口', '席力图召位于呼和浩特市玉泉区，是呼和浩特地区现存规模最大、保存最完整的藏传佛教寺院之一，始建于明万历十三年（1585年），距今已有430多年历史。席力图召的蒙古语意为"首席"或"法座"，因四世达赖喇嘛幼年曾在此学经而得名，是呼和浩特藏传佛教的重要寺院之一。', 'attraction', '呼和浩特', '30元/人（成人），15元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1078, '五塔寺（慈灯寺塔）', '呼和浩特市玉泉区五塔寺后街48号', '五塔寺位于呼和浩特市玉泉区，原名慈灯寺，因寺内建有五座小型佛塔而得名"五塔寺"。五塔寺始建于清雍正五年（1727年），寺内的五塔（金刚座舍利宝塔）是呼和浩特地区现存最完整的清代金刚座式佛塔，也是全国重点文物保护单位。', 'attraction', '呼和浩特', '15元/人（成人），8元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1079, '内蒙古博物院', '呼和浩特市新城区新华东街27号', '内蒙古博物院位于呼和浩特市新城区，是内蒙古自治区最大的综合性博物馆，也是国家一级博物馆。博物院占地面积约5万平方米，建筑面积约5万平方米，收藏有各类文物和标本10万余件（套），其中珍贵文物约2万余件（套），是了解内蒙古历史文化和自然资源的重要窗口。', 'attraction', '呼和浩特', '免费开放（需提前预约）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1080, '格日勒阿妈奶茶馆（总店）', '呼和浩特市回民区通道街68号', '格日勒阿妈奶茶馆是呼和浩特最有名的蒙古族特色餐厅，创立已有20多年，以正宗的蒙古族奶茶和各种奶制品、肉类食品而著称。奶茶用砖茶、鲜奶、盐等熬制而成，味道咸香，营养丰富，是抵御严寒的佳品。', 'restaurant', '呼和浩特', '50-100元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1081, '蒙古大营（总店）', '呼和浩特市新城区成吉思汗大街东段', '蒙古大营是呼和浩特最具特色的蒙古族风味餐厅，建筑为传统蒙古包样式，内部装饰充满蒙古民族特色，提供正宗的蒙古族美食，是体验蒙古族饮食文化的绝佳去处。', 'restaurant', '呼和浩特', '100-200元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1082, '焙子（呼和浩特特色小吃）', '呼和浩特市回民区旧城北门一带（多家小摊）', '焙子是呼和浩特的传统小吃，用面粉发酵后烙制而成，外皮酥脆，内里松软，有咸甜多种口味，是呼和浩特人最喜爱的早餐之一。', 'restaurant', '呼和浩特', '5-15元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1083, '羊肉稍美（烧麦）', '呼和浩特市玉泉区大召附近（多家餐厅）', '稍美（烧麦）是呼和浩特的传统特色小吃，用烫面做皮，羊肉大葱做馅，皮薄馅大，鲜香味美，是呼和浩特人最喜爱的早餐之一。', 'restaurant', '呼和浩特', '30-60元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1084, '武川莜面', '呼和浩特市新城区哲里木路102号', '武川莜面是呼和浩特的传统面食，用莜麦（裸燕麦）磨粉制成，营养丰富，口感筋道，搭配羊肉汤或酸菜汤，鲜香味美，是体验呼和浩特地方特色美食的绝佳去处。', 'restaurant', '呼和浩特', '30-60元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1085, '呼和浩特香格里拉大酒店', '呼和浩特市新城区锡林郭勒南路5号', '五星级豪华酒店，位于市区核心地段，装修典雅豪华，设施一流，服务优质，是商务出行和高端旅游的理想选择。', 'hotel', '呼和浩特', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1086, '呼和浩特喜来登酒店', '呼和浩特市新城区如意南路52号', '五星级商务酒店，位于如意开发区，环境优美，设施豪华，客房宽敞舒适，服务细致入微，是呼和浩特市标志性豪华酒店之一。', 'hotel', '呼和浩特', '600-1500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1087, '如家酒店（呼和浩特火车站店）', '呼和浩特市新城区车站西街88号', '经济型连锁酒店，位于呼和浩特火车站附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '呼和浩特', '150-280元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1088, '呼和浩特蒙古风情民宿', '呼和浩特市新城区大青山脚下（多家民宿）', '蒙古包特色民宿，位于大青山脚下，可以体验蒙古包住宿、蒙古族美食、骑马射箭等草原文化，是体验蒙古族生活的绝佳选择。', 'hotel', '呼和浩特', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1089, '呼和浩特古城民宿', '呼和浩特市玉泉区大召附近（多家民宿）', '古色古香的民宿，位于大召附近，建筑风格古朴典雅，充满历史韵味，是体验呼和浩特古城文化、感受蒙古民俗的理想住宿选择。', 'hotel', '呼和浩特', '120-300元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1090, '云冈石窟', '大同市云冈区云冈镇云冈路1号', '云冈石窟位于大同市西16公里的武周山南麓，是中国四大石窟之一，也是世界文化遗产、国家AAAAA级旅游景区。云冈石窟始建于北魏兴安二年（453年），由高僧昙曜主持开凿，历经60余年建成，现存主要洞窟45个，大小石雕造像51000余尊，是中国佛教艺术第一个巅峰时期的经典之作。', 'attraction', '大同', '120元/人（旺季），100元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1091, '悬空寺', '大同市浑源县悬空寺景区', '悬空寺位于大同市浑源县恒山金龙峡西侧翠屏峰的半崖峭壁之上，始建于北魏后期（约471-523年），距今已有约1500年历史，是中国仅存的佛、道、儒三教合一的独特寺庙。悬空寺以"奇、悬、巧"著称，整座寺院建在距地面约50米的悬崖峭壁之上，利用力学原理半插飞梁为基，巧借岩石暗托，梁柱上下一体，廊栏左右相连，虚实相生，错落有致。', 'attraction', '大同', '125元/人（含登临费）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1092, '华严寺', '大同市平城区下寺坡街459号', '华严寺位于大同市平城区，始建于辽重熙七年（1038年），是我国现存年代较早、保存较完整的一座辽金寺庙建筑群，也是全国重点文物保护单位。华严寺坐西向东，与一般汉地寺庙坐北朝南的布局迥然不同，这是辽代寺庙的典型布局特征，反映了辽代契丹族"崇拜太阳、以东为尊"的文化传统。', 'attraction', '大同', '50元/人（成人），25元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1093, '九龙壁', '大同市平城区大东街18号', '九龙壁位于大同市平城区大东街，建于明洪武二十五年（1392年），是明太祖朱元璋第十三子朱桂王府前的照壁，也是中国现存规模最大、建筑年代最早的琉璃照壁，比北京故宫九龙壁早350年，比北京北海九龙壁早450年。九龙壁长45.5米，高8米，厚2.02米，壁上建有九条巨龙，颜色分别为：黄、紫、黑、赭、蓝、白、绿、红、青，九条龙神态各异，栩栩如生，壁前倒影池更增添了九龙壁的灵动之美。', 'attraction', '大同', '10元/人（成人），5元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1094, '恒山', '大同市浑源县大磁窑村', '恒山位于大同市浑源县境内，是中国五岳之一的北岳，与东岳泰山、西岳华山、南岳衡山、中岳嵩山并称五岳。恒山主峰天峰岭海拔2016.1米，山势陡峭，沟谷深邃，道路险峻，自古就有"人天北柱""绝塞名山"之美誉。恒山是著名的道教圣地，相传道教八仙之一的张果老曾在恒山修道炼丹，山上有大量与张果老相关的遗迹和传说。', 'attraction', '大同', '55元/人（入山费），125元/人（含悬空寺）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1095, '大同刀削面（老柴家）', '大同市平城区仿古街32号', '大同刀削面是山西面食的代表之一，以刀功精湛、面片筋道、卤汁鲜美而著称。老柴家刀削面是大同最有名的面食店，已有30多年历史，是品尝正宗大同刀削面的绝佳去处。', 'restaurant', '大同', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1096, '浑源凉粉', '大同市浑源县永安西街18号', '浑源凉粉是大同浑源县的特色小吃，用土豆淀粉制成凉粉，搭配特制的辣椒油、蒜泥、醋等调料，酸辣可口，清爽解暑，是夏季消暑的佳品，也是浑源县最具代表性的特色小吃。', 'restaurant', '大同', '10-25元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1097, '大同涮羊肉', '大同市平城区魏都大道88号', '大同涮羊肉是大同的特色美食，选用大同及周边地区放养的羔羊，肉质鲜嫩，膻味小，用传统铜锅涮煮，搭配芝麻酱、韭菜花、腐乳等蘸料，鲜香味美，是冬季进补的佳品。', 'restaurant', '大同', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1098, '大同黄糕', '大同市平城区大西街56号（小吃摊聚集区）', '黄糕是大同的传统小吃，用黄米面制成，口感软糯，香甜可口。黄糕可以素吃（蘸白糖或蜂蜜），也可以油炸（油糕），是大同人最喜爱的传统小吃之一。', 'restaurant', '大同', '10-20元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1099, '大同兔头', '大同市平城区新建北路102号', '兔头是大同的特色小吃，用多种香料卤制而成，肉质鲜嫩，味道醇香，是大同人最喜爱的夜宵之一。麻辣兔头香辣扑鼻，五香兔头香味浓郁，令人回味无穷。', 'restaurant', '大同', '30-60元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1100, '大同金地豪生大酒店', '大同市平城区迎宾街88号', '五星级豪华酒店，位于市区核心地段，装修典雅豪华，设施一流，服务优质，是商务出行和高端旅游的理想选择。', 'hotel', '大同', '600-1200元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1101, '大同云中传统四合院', '大同市平城区古城内（华严寺附近）', '古色古香的传统四合院民宿，位于大同古城内，建筑风格古朴典雅，充满历史韵味，是体验大同古城文化、感受晋北民俗的理想住宿选择。', 'hotel', '大同', '300-600元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1102, '如家酒店（大同火车站店）', '大同市平城区站前街56号', '经济型连锁酒店，位于大同火车站附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '大同', '150-280元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1103, '大同恒山大酒店', '大同市浑源县恒山景区入口处', '位于恒山景区入口处，环境清幽，空气清新，是游览恒山和悬空寺的理想下榻之处。', 'hotel', '大同', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1104, '大同古城民宿聚集区', '大同市平城区古城内（大西街、大东街周边）', '大同古城内有大量家庭式民宿，价格实惠，主人热情好客，提供家常菜和旅游咨询服务，是体验大同本地生活的经济之选。', 'hotel', '大同', '120-300元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1105, '五大道文化旅游区', '天津市和平区重庆道70号（五大道游客服务中心）', '五大道文化旅游区位于天津市和平区，是天津历史文化街区的典型代表，被誉为“万国建筑博览会”。五大道是指马场道、睦南道、大理道、常德道、重庆道这五条平行的道路，实际范围还包括成都道等周边区域，总面积约1.28平方公里。这里汇聚了上世纪20-30年代建成的英、法、意、德、西班牙等不同国家建筑风格的花园式房屋2000多所，其中名人旧居300余幢，被誉为“世界建筑博览会”。', 'attraction', '天津', '免费开放（部分名人旧居单独收费，如张学良故居20元/人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1106, '天津之眼摩天轮', '天津市河北区三岔河口永乐桥上', '天津之眼全称“天津永乐桥摩天轮”，位于天津市河北区三岔河口永乐桥上，是天津的地标性建筑之一。摩天轮直径为110米，轮外装挂48个360度透明座舱，每个座舱可乘坐8人，可同时供384人观光。摩天轮旋转一周所需时间为30分钟，到达最高处时，周边景色一览无余，甚至可以看到方圆40公里以内的景致。', 'attraction', '天津', '70元/人（成人），35元/人（儿童/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1107, '古文化街', '天津市南开区通北路（海河西岸）', '天津古文化街又称“津门故里”，位于天津市南开区东北角东门外，海河西岸，是天津十大景观之一，国家AAAA级旅游景区。古文化街全长687米，以天后宫为中心，南北走向，南起水阁大街，北至通北路。街道两侧店铺林立，主要经营文化用品、古玩字画、传统手工艺品等，是天津老字号店铺的集中地。', 'attraction', '天津', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1108, '意大利风情旅游区', '天津市河北区光复道39号', '天津意大利风情旅游区位于天津市河北区，是原意大利租界，也是意大利本土之外最大的意大利风格建筑群。区域内有历史建筑百余栋，包括领事馆、兵营、住宅、教堂、花园等，建筑风格主要为意大利文艺复兴时期风格，充满了异域风情。', 'attraction', '天津', '免费开放（部分展馆单独收费）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1109, '瓷房子', '天津市和平区赤峰道72号', '瓷房子位于天津市和平区赤峰道72号，是一座用多件古瓷器修建而成的法式洋楼，被誉为“中国古瓷博物馆”。瓷房子原是20世纪20年代后期所建的经典法式洋楼，年久失修，后由收藏家张连志先生耗资数百万美元，用多年收藏的历代瓷器、汉白玉石雕、水晶石和玛瑙等珍贵材料进行装饰装修，使其成为了一座独一无二的艺术建筑。', 'attraction', '天津', '50元/人（成人），25元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1110, '黄崖关长城', '天津市蓟州区下营镇黄崖关长城景区', '黄崖关长城位于天津市蓟州区北30公里的崇山峻岭之中，始建于北齐天保七年（556年），明代又进行了大规模增修，是明代长城的重要关隘之一，也是津门十景之首。黄崖关长城东起河北省遵化市的马兰关，西至北京市平谷区的将军关，全长42公里，其中在天津蓟州区内长约40公里。', 'attraction', '天津', '65元/人（成人），35元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1111, '狗不理包子（山东路总店）', '天津市和平区山东路77号', '狗不理包子是天津“三绝”之首，始创于公元1858年（清咸丰年间），至今已有160余年的历史。狗不理包子以其鲜香味美、清香适口而闻名遐迩，包子制作工艺独特，选料精细，皮薄馅大，口感鲜香不腻。山东路总店是狗不理包子的发源地和旗舰店，装修风格古色古香，保留了传统的天津风貌。', 'restaurant', '天津', '60-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1112, '桂发祥十八街麻花（河西总店）', '天津市河西区大沽南路566号', '桂发祥十八街麻花是天津“三绝”之一，与狗不理包子、耳朵眼炸糕齐名。十八街麻花因店铺原址位于天津大沽南路十八街而得名，距今已有百年历史。麻花讲究甜、酥、脆、香，色泽金黄，口感酥脆，久放不绵，是天津最具代表性的特色小吃和伴手礼。', 'restaurant', '天津', '30-50元（购买伴手礼）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1113, '耳朵眼炸糕（北马路店）', '天津市红桥区北马路128号', '耳朵眼炸糕是天津“三绝”之一，始创于清光绪年间（1900年），因店铺原址位于天津卫耳朵眼胡同而得名。炸糕选用优质糯米粉作皮，以红豆沙、黑芝麻等为馅，经低温油炸而成，成品色泽金黄，外皮酥脆，内馅软糯，香甜可口，是天津传统小吃的代表。', 'restaurant', '天津', '10-20元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1114, '起士林大饭店（小白楼店）', '天津市和平区浙江路33号', '起士林是天津最早的西餐厅，始建于1901年，由德国厨师起士林创办，是天津西餐文化的代表。餐厅建筑为德式风格，内部装修典雅豪华，提供正宗的德式、俄式、法式西餐，是天津历史最悠久、最具知名度的西餐厅之一。', 'restaurant', '天津', '150-200元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1115, '大胡同老城里四姐麻辣烫', '天津市南开区大胡同32号', '大胡同老城里四姐麻辣烫是天津本地非常有名的麻辣烫店，创立已有20多年，以秘制汤底和丰富食材著称。汤底麻辣鲜香，食材新鲜多样，包括各种蔬菜、豆制品、丸滑类、肉类等，是天津人喜爱的平价美食之一。', 'restaurant', '天津', '25-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1116, '天津瑞吉金融街酒店', '天津市和平区张自忠路158号', '超五星级豪华酒店，位于海河之滨，紧邻意大利风情区，客房可俯瞰海河美景，服务一流，设施豪华，适合高端商务及度假旅客。', 'hotel', '天津', '1200-2500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1117, '天津利顺德大饭店', '天津市和平区台儿庄路33号', '始建于1863年，是中国历史最悠久的酒店之一，全国重点文物保护单位，维多利亚建筑风格，保留了百年前的电梯、家具等历史遗迹，文化氛围浓厚，被誉为“华夏第一店”。', 'hotel', '天津', '600-1200元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1118, '天津海河悦榕庄酒店', '天津市河北区海河东路34号', '国际奢华酒店品牌，位于海河河畔，紧邻古文化街，设计融合了中国古典元素与现代风格，客房宽敞舒适，服务细致入微，是天津标志性豪华酒店之一。', 'hotel', '天津', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1119, '如家酒店（天津和平路步行街店）', '天津市和平区和平路237号', '经济型连锁酒店，位于和平路步行街核心地段，购物交通便利，周边有众多餐饮和娱乐场所，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '天津', '200-350元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1120, '汉庭酒店（天津站前广场店）', '天津市河北区海河东路78号', '位于天津站前广场附近，交通极为便利，步行可达天津站和海河观光带，周边餐饮、购物设施齐全，是商务出行和自助游的经济实惠之选。', 'hotel', '天津', '180-300元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1121, '晋祠景区', '太原市晋源区晋祠镇晋祠路2号', '晋祠位于太原市西南25公里的悬瓮山麓，晋水源头，是中国现存最早的皇家祭祀园林，也是全国重点文物保护单位，国家AAAA级旅游景区。晋祠始建于西周时期（公元前11世纪），是为纪念晋国开国诸侯唐叔虞而建，历经各代修葺扩建，形成了集祭祀建筑、园林、雕塑、壁画、碑刻艺术为一体的珍贵历史文化遗产。', 'attraction', '太原', '80元/人（成人），40元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1122, '山西博物院', '太原市滨河西路北段13号', '山西博物院位于太原市汾河西岸，是山西省最大的文物收藏、保护、研究和展示中心，国家一级博物馆。博物院占地面积约7.3万平方米，建筑面积约5.2万平方米，收藏有各类文物40余万件，其中珍贵文物约4万余件，包括一级文物约2000件。', 'attraction', '太原', '免费开放（需提前预约）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1123, '天龙山石窟', '太原市晋源区天龙山景区', '天龙山石窟位于太原市西南40公里的天龙山，是南北朝至隋唐时期重要的佛教石窟艺术遗址，始凿于东魏武定二年（544年），后历经北齐、隋、唐各代连续开凿，形成了25个洞窟、500余尊造像的规模。天龙山石窟以精美的佛像造型和细腻的雕刻技艺而著称，被誉为"东方雕塑艺术的宝库"。', 'attraction', '太原', '50元/人（成人），25元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1124, '蒙山大佛', '太原市晋源区罗城街道蒙山大佛景区', '蒙山大佛位于太原市西南约20公里的蒙山，是一尊北齐时期开凿的摩崖大佛，距今已有约1500年历史。蒙山大佛开凿于北齐天保年间（550-559年），佛身高约63米，比著名的乐山大佛（71米）略低，但开凿时间比乐山大佛早162年，是中国现存最早的大型摩崖造像之一。', 'attraction', '太原', '50元/人（成人），25元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1125, '太原古县城', '太原市晋源区太原古县城景区', '太原古县城位于太原市晋源区，是在明代太原县城（晋源古城）的基础上修复重建的，占地面积约0.8平方公里，总建筑面积约36万平方米。古县城城垣方整，街道规整，保留了明代县城的基本格局，被誉为"凤凰城"。', 'attraction', '太原', '免费开放（部分景点收费）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1126, '山西刀削面（太原老字号）', '太原市迎泽区柳巷北路56号', '刀削面是山西最具代表性的面食，始于元代，以刀功闻名——厨师一手托面团，一手持特制弯刀，削出的面片形似柳叶，中厚边薄，入口筋道滑爽。太原老字号刀削面馆是太原最有名的面食店，已有50多年历史，是品尝正宗山西面食的绝佳去处。', 'restaurant', '太原', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1127, '太原头脑', '太原市迎泽区桥头街28号', '头脑是太原特有的传统名吃，又名"八珍汤"，由黄芪、良姜、羊肉、山药、藕根、面精、酒糟等八种原料配制而成，味道独特，营养丰富，是太原人最喜爱的早餐之一。', 'restaurant', '太原', '15-30元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1128, '山西老陈醋（宁化府）', '太原市迎泽区桥头街宁化府巷18号（特产店）', '山西老陈醋是中国四大名醋之一，距今已有3000余年的历史，素有"天下第一醋"之美誉。宁化府是太原最著名的老陈醋品牌，醋香浓郁，酸味醇厚，久放不腐，是太原最具代表性的伴手礼之一。', 'restaurant', '太原', '30-100元（购买伴手礼）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1129, '过油肉', '太原市迎泽区食品街32号', '过油肉是山西最著名的传统菜肴，被誉为"三晋一味"，始于明代，已有数百年的历史。选料讲究，制作精细，色泽金黄，味道咸鲜，外软里嫩，是山西菜系的代表之作，也是到太原必尝的特色美食。', 'restaurant', '太原', '40-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1130, '太原羊杂割', '太原市杏花岭区解放路102号', '羊杂割是太原的传统小吃，用羊肚、羊肝、羊肺、羊肠等羊杂碎，配以粉条、香菜、辣椒等烹制而成，汤色乳白，味道鲜美，辣香扑鼻，是太原人最喜爱的早餐和夜宵之一。', 'restaurant', '太原', '25-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1131, '太原凯宾斯基饭店', '太原市小店区长风商务区谐园路6号', '五星级豪华酒店，位于长风商务区，紧邻汾河公园，装修典雅豪华，设施一流，服务优质，是商务出行和高端旅游的理想选择。', 'hotel', '太原', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1132, '太原星河湾酒店', '太原市小店区星河中路2号', '五星级商务酒店，位于星河湾小区内，环境优美，设施豪华，客房宽敞舒适，服务细致入微，是太原市标志性豪华酒店之一。', 'hotel', '太原', '600-1500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1133, '如家酒店（太原柳巷店）', '太原市迎泽区柳巷南路78号', '经济型连锁酒店，位于柳巷商业街核心地段，购物交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '太原', '150-280元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1134, '太原古县城民宿', '太原市晋源区太原古县城内', '古色古香的主题民宿，位于太原古县城内，建筑风格古朴典雅，充满明清韵味，是体验古城文化、感受山西民俗的理想住宿选择。', 'hotel', '太原', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1135, '太原晋祠宾馆', '太原市晋源区晋祠路2号（晋祠对面）', '四星级园林式酒店，位于晋祠对面，环境清幽，空气清新，客房分布在花园般的环境中，是游览晋祠后理想的休息之处。', 'hotel', '太原', '400-800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1136, '天一阁博物院', '宁波市海曙区天一街10号', '天一阁位于宁波市海曙区，是中国现存最早的私家藏书楼，也是亚洲现有最古老的图书馆，始建于明嘉靖四十年（1561年），由明代兵部右侍郎范钦主持修建，距今已有460多年历史，是宁波最具标志性的文化景观之一，国家AAAA级旅游景区。', 'attraction', '宁波', '30元/人（成人），15元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1137, '奉化溪口景区', '宁波市奉化区溪口镇中山路18号', '奉化溪口景区位于宁波市奉化区溪口镇，是蒋介石、蒋经国父子的故里，也是近代中国历史的重要见证地，国家AAAAA级旅游景区。溪口镇沿剡溪而建，三面环山，一面临水，风光旖旎，素有“应梦名山”“剡溪明珠”之美誉。', 'attraction', '宁波', '230元/人（联票，含雪窦山），150元/人（溪口镇区）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1138, '东钱湖旅游度假区', '宁波市鄞州区东钱湖镇', '东钱湖位于宁波市鄞州区，是浙江最大的天然淡水湖，水域面积约为西湖的3.5倍，素有“西子风韵，太湖气魄”之美誉。东钱湖旅游度假区占地面积约230平方公里，其中水域面积约20平方公里，湖岸线长约45公里，是宁波最具代表性的自然风光旅游区。', 'attraction', '宁波', '免费开放（部分景点收费）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1139, '宁波老外滩', '宁波市江北区人民路（甬江入海口）', '宁波老外滩位于宁波市江北区甬江入海口，是中国最早的外滩之一，也是宁波最具标志性的近代建筑街区，始建于1844年（清道光二十四年），距今已有180多年历史，是宁波作为“五口通商”口岸之一的历史见证。', 'attraction', '宁波', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1140, '雪窦山风景名胜区', '宁波市奉化区溪口镇雪窦山景区', '雪窦山位于宁波市奉化区溪口镇西侧，是四明山支脉的最高峰，海拔800米，因山上有乳峰，峰顶有窦，宛如乳之水滴，故名“雪窦山”。雪窦山是弥勒菩萨的根本道场，被誉为“天下禅宗圣地”，也是国家AAAAA级旅游景区。', 'attraction', '宁波', '150元/人（含在溪口联票内），单独门票80元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1141, '宁波汤团（缸鸭狗总店）', '宁波市海曙区开明街123号', '缸鸭狗始创于1926年（民国十五年），是宁波最著名的汤团专营店，也是商务部首批认定的“中华老字号”餐饮企业。以宁波汤团为代表作，汤团皮薄馅大，汤汁鲜美，是宁波最具代表性的特色小吃之一。', 'restaurant', '宁波', '30-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1142, '宁波海鲜（石浦饭店总店）', '宁波市海曙区中山东路256号', '石浦饭店始创于1988年，是宁波最具代表性的海鲜餐厅，以宁波本帮海鲜菜为主，海鲜新鲜，做工精细，口味鲜美，是品尝地道宁波海鲜的首选餐厅。', 'restaurant', '宁波', '100-180元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1143, '宁波年糕（慈城年糕）', '宁波市江北区慈城镇（多家年糕店）', '慈城年糕是宁波的传统特色食品，已有数百年历史，以糯米粉制成，口感软糯，可以炒、煮、烤、炸，是宁波人最喜爱的家常美食之一。', 'restaurant', '宁波', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1144, '宁波霉豆腐（冷饮食品店）', '宁波市海曙区鼓楼步行街32号', '霉豆腐是宁波的传统特色小吃，用豆腐发酵后制成，闻起来臭，吃起来香，是宁波最具代表性的“臭味”美食之一。', 'restaurant', '宁波', '15-30元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1145, '宁波小吃聚集区（鼓楼步行街、南塘老街）', '宁波市海曙区鼓楼步行街、南塘老街', '鼓楼步行街和南塘老街是宁波最著名的小吃聚集区，汇聚了宁波各种特色小吃和老字号餐厅，是品尝宁波特色美食、体验宁波民俗文化的绝佳去处。', 'restaurant', '宁波', '40-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1146, '宁波香格里拉大酒店', '宁波市鄞州区豫源街88号', '五星级豪华酒店，位于甬江畔，部分客房可俯瞰甬江入海口美景，设施豪华，服务一流，是商务出行和高端旅游的理想选择。', 'hotel', '宁波', '1000-2500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1147, '宁波威斯汀酒店', '宁波市海曙区和义大道99号', '五星级商务酒店，位于和义大道商务区，紧邻老外滩，装修典雅豪华，设施一流，服务优质，是宁波市标志性豪华酒店之一。', 'hotel', '宁波', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1148, '如家酒店（宁波天一广场店）', '宁波市海曙区中山东路528号', '经济型连锁酒店，位于天一广场核心地段，购物交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '宁波', '180-320元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1149, '奉化溪口民宿聚集区', '宁波市奉化区溪口镇内（多家民宿）', '民国风情民宿聚集区，位于溪口镇内，建筑风格古朴典雅，充满民国韵味，是体验蒋氏故里文化、感受溪口慢生活的理想住宿选择。', 'hotel', '宁波', '150-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1150, '东钱湖度假酒店', '宁波市鄞州区东钱湖镇旅游度假区内', '四星级度假酒店，位于东钱湖畔，环境清幽，空气清新，是游览东钱湖后理想的休息之处。', 'hotel', '宁波', '600-1500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1151, '广州塔（小蛮腰）', '广州市海珠区阅江西路222号', '广州塔位于广州市海珠区阅江西路，是一座以观光旅游为主的大型电视塔，也是国家AAAA级旅游景区。广州塔塔高600米，其中主体塔高454米，天线桅杆高146米，是中国第一、世界第二高塔，因其腰身纤细、造型独特，被市民亲切地称为“小蛮腰”。', 'attraction', '广州', '150-298元/人（根据观光层不同）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1152, '白云山风景名胜区', '广州市白云区广园中路801号', '白云山位于广州市白云区，是南粤名山之一，也是国家AAAA级旅游景区。白云山因山间常有白云飘绕而得名，最高点摩星岭海拔382米，是广州的“市肺”和“羊城第一秀”，自古就有“羊城第一秀”之美誉。', 'attraction', '广州', '5元/人（进山费），部分景点单独收费', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1153, '长隆野生动物世界', '广州市番禺区汉溪大道东299号', '长隆野生动物世界位于广州市番禺区，是长隆旅游度假区的重要组成部分，也是国家AAAAA级旅游景区。长隆野生动物世界占地面积约2000余亩，放养着以“十大世界珍稀动物国宝”为代表的500余种、20000余只珍稀动物，是中国最大的野生动物园之一。', 'attraction', '广州', '300元/人（成人），210元/人（儿童/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1154, '陈家祠（陈氏书院）', '广州市荔湾区中山七路恩龙里34号', '陈家祠位于广州市荔湾区，是清代广东陈氏宗族合族合资兴建的宗族祠书院，也是广东现存规模最大、保存最完好的传统岭南祠堂式建筑，素有“岭南建筑艺术瑰宝”之美誉，国家AAAA级旅游景区。', 'attraction', '广州', '10元/人（成人），5元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1155, '沙面历史文化街区', '广州市荔湾区沙面街道（沿沙面南街、沙面北街）', '沙面位于广州市荔湾区，是珠江冲积而成的沙洲，故名“沙面”，也是广州最具代表性的历史文化街区，素有“广州西贡”“露天建筑博物馆”之美誉。沙面始建于清咸丰九年（1859年），是英法联军占领广州后的英法租界，至今已有160多年历史。', 'attraction', '广州', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1156, '广州酒家（文昌总店）', '广州市荔湾区文昌南路2号', '广州酒家始创于1935年，是广州最著名的餐饮品牌之一，以正宗粤菜和精致点心为主，文昌鸡是广州酒家的招牌菜，皮脆肉嫩，鲜香味美，是体验正宗粤菜的首选餐厅。', 'restaurant', '广州', '100-200元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1157, '点都德（天河城店）', '广州市天河区天河路208号天河城6楼', '点都德是广州最具代表性的茶楼之一，以正宗广式点心和早茶为主，虾饺皮薄馅大，汁水饱满，是体验广州“吃早茶”文化的绝佳去处。', 'restaurant', '广州', '60-100元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1158, '炳胜品味（珠江新城店）', '广州市天河区花城大道68号', '炳胜品味是广州最具代表性的粤菜餐厅之一，以正宗粤菜和海鲜为主，做工精细，口味清淡鲜美，是体验广州本帮菜的首选餐厅。', 'restaurant', '广州', '120-220元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1159, '陈添记鱼皮（宝华路总店）', '广州市荔湾区宝华路83号', '陈添记鱼皮是广州最有名的传统小吃店，创立已有30多年，以鱼皮爽脆、粥底绵滑而著称，是广州人最喜爱的宵夜之一。', 'restaurant', '广州', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1160, '广州小吃聚集区（上下九步行街、北京路步行街）', '广州市荔湾区上下九步行街、越秀区北京路步行街', '上下九步行街和北京路步行街是广州最著名的小吃聚集区，汇聚了广州各种特色小吃和老字号餐厅，是品尝广州美食、体验羊城风情的绝佳去处。', 'restaurant', '广州', '40-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1161, '广州四季酒店', '广州市天河区珠江西路5号', '超五星级豪华酒店，位于珠江新城核心地段，部分客房可俯瞰珠江美景和小蛮腰，设施豪华，服务一流，是商务出行和高端旅游的理想选择。', 'hotel', '广州', '1500-3500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1162, '广州白天鹅宾馆', '广州市荔湾区沙面街道沙面南街1号', '五星级豪华酒店，位于沙面岛上，是中国第一家中外合作的五星级酒店，装修典雅，环境清幽，服务优质，是广州市标志性豪华酒店之一。', 'hotel', '广州', '1000-2500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1163, '如家酒店（广州北京路店）', '广州市越秀区北京路312号', '经济型连锁酒店，位于北京路步行街核心地段，购物交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '广州', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1164, '广州沙面民宿聚集区', '广州市荔湾区沙面街道内（多家民宿）', '历史建筑改建的民宿聚集区，位于沙面岛上，建筑风格充满欧陆风情，是体验广州近代史、感受沙面慢生活的理想住宿选择。', 'hotel', '广州', '200-600元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1165, '广州长隆酒店', '广州市番禺区汉溪大道东299号（长隆度假区内）', '主题度假酒店，位于长隆旅游度假区内，部分客房可看到野生动物园的白虎、大熊猫等，是亲子游的理想住宿选择。', 'hotel', '广州', '800-2000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1166, '崇礼滑雪旅游度假区', '张家口市崇礼区西湾子镇冰雪大街1号', '崇礼滑雪旅游度假区位于张家口市崇礼区，是2022年北京冬奥会雪上项目的主要举办地，也是中国最大的滑雪聚集区之一。崇礼区海拔从814米到2174米不等，年平均气温3.3°C，积雪期长达150多天，滑雪期达120多天，是中国滑雪条件最优越的地区之一。', 'attraction', '张家口', '滑雪票约200-500元/人/天（根据雪场和季节）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1167, '草原天路', '张家口市张北县与崇礼区交界处（西起野狐岭，东至桦皮岭）', '草原天路位于张家口市张北县和崇礼区的交界处，西起张北县城南侧野狐岭，东至崇礼县桦皮岭，全长132.7公里，被誉为"中国的66号公路"。草原天路于2012年建成通车，沿途穿越坝上草原，风光旖旎，有草原、风车、梯田、桦树林、花海等多种景观，是自驾游和摄影爱好者的天堂。', 'attraction', '张家口', '免费开放（部分景点单独收费）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1168, '大境门景区', '张家口市桥西区明德北路三角地大街1号', '大境门位于张家口市桥西区北端，是万里长城的重要关隘之一，也是张家口市的标志性建筑。大境门建于清顺治元年（1644年），是在明代长城的基础上增筑而成的，门楣上刻有"大好河山"四个大字，为1927年察哈尔督统高维岳所题，笔力雄健，气势磅礴。', 'attraction', '张家口', '30元/人（成人），15元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1169, '暖泉古镇', '张家口市蔚县暖泉镇', '暖泉古镇位于张家口市蔚县西部，是中国历史文化名镇，也是典型的北方古镇。暖泉古镇因镇上有温泉而得名，泉水四季常温，寒冬不结冰，故得名"暖泉"。古镇始建于元代，兴于明清，保存有大量明清时期的古建筑，包括古民居、古寺庙、古戏楼、古城墙等，是了解北方古镇文化的绝佳去处。', 'attraction', '张家口', '60元/人（成人），30元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1170, '黄帝城遗址文化旅游区', '张家口市涿鹿县矾山镇黄帝城遗址', '黄帝城遗址文化旅游区位于张家口市涿鹿县矾山镇，是中华文明的重要发祥地之一，相传是黄帝、炎帝、蚩尤三位中华人文始祖征战、会盟、融合的地方。景区内有黄帝城遗址、黄帝泉、蚩尤寨、炎帝营等多处历史文化遗迹，是了解中华文明起源、体验炎黄文化的重要场所。', 'attraction', '张家口', '50元/人（成人），25元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1171, '张家口莜面村', '张家口市桥西区至善街28号', '莜面是张家口地区的传统面食，用莜麦（裸燕麦）磨粉制成，营养丰富，口感筋道。莜面村是张家口最有名的莜面专营餐厅，提供各种莜面制品，包括莜面窝窝、莜面鱼鱼、莜面饸饹等，搭配羊肉汤或酸菜汤，鲜香味美，是体验张家口地方特色美食的绝佳去处。', 'restaurant', '张家口', '30-60元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1172, '柴沟堡熏肉', '张家口市怀安县柴沟堡镇迎宾路12号（特产店）', '柴沟堡熏肉是张家口怀安县的特色食品，始创于清乾隆年间，已有200多年历史。熏肉选用优质猪肉，用多种香料和果木熏制而成，色泽红润，味道醇香，肥而不腻，瘦而不柴，是张家口最具代表性的伴手礼之一。', 'restaurant', '张家口', '30-80元（购买伴手礼）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1173, '蔚县豆腐干', '张家口市蔚县蔚州镇人民路56号', '蔚县豆腐干是张家口蔚县的传统小吃，用优质黄豆制成，质地紧实，豆香浓郁，有五香、麻辣、孜然等多种口味，是蔚县最具代表性的特色小吃和伴手礼。', 'restaurant', '张家口', '10-30元（购买伴手礼）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1174, '坝上羊肉馆', '张家口市桥东区胜利中路102号', '坝上羊肉馆是张家口有名的特色餐厅，选用坝上草原放养的羔羊，肉质鲜嫩，膻味小，用传统工艺烹制而成，包括手把肉、烤全羊、羊肉火锅等多种做法，是品尝坝上草原美食的绝佳去处。', 'restaurant', '张家口', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1175, '张家口奶茶馆', '张家口市桥西区明德北路45号', '奶茶是坝上草原蒙古族的传统饮品，用砖茶、鲜奶、盐等熬制而成，味道咸香，营养丰富，是抵御严寒的佳品。奶茶馆提供正宗的蒙古族奶茶和各类奶制品，是体验蒙古族饮食文化的绝佳去处。', 'restaurant', '张家口', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1176, '张家口崇礼太舞度假酒店', '张家口市崇礼区太舞滑雪场区内', '五星级滑雪度假酒店，位于太舞滑雪场内，设施豪华，服务一流，滑雪季节可直接滑进滑出，是滑雪爱好者的理想下榻之处。', 'hotel', '张家口', '800-2000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1177, '张家口蓝鲸大厦', '张家口市桥东区胜利中路241号', '四星级商务酒店，位于市区核心地段，交通便利，设施齐全，房间宽敞舒适，是商务出行和旅游度假的实惠之选。', 'hotel', '张家口', '300-600元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1178, '如家酒店（张家口火车站店）', '张家口市桥东区站前西大街88号', '经济型连锁酒店，位于张家口火车站附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '张家口', '150-280元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1179, '蔚县暖泉古镇民宿', '张家口市蔚县暖泉镇内', '古色古香的古镇民宿，位于暖泉古镇内，建筑风格古朴典雅，充满历史韵味，是体验古镇文化、感受北方民俗的理想住宿选择。', 'hotel', '张家口', '100-250元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1180, '张北草原天路民宿', '张家口市张北县草原天路沿线', '草原特色民宿，位于草原天路沿线，部分民宿提供蒙古包住宿体验，可以品尝手把肉、奶茶等蒙古族美食，是体验草原文化的绝佳选择。', 'hotel', '张家口', '120-300元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1181, '瘦西湖景区', '扬州市邗江区大虹桥路28号', '瘦西湖位于扬州市西北部，是扬州最具标志性的景观，也是世界文化遗产大运河的重要组成部分，国家AAAAA级旅游景区。瘦西湖原名“保障湖”，因湖面瘦长、蜿蜒曲折而得名“瘦西湖”，湖身全长约4.3公里，游览面积达168.32公顷。', 'attraction', '扬州', '100元/人（旺季），60元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1182, '个园', '扬州市广陵区盐阜东路10号', '个园位于扬州市广陵区，是清代嘉庆二十三年（1818年）盐商黄至筠在明代“寿芝园”旧址上扩建而成的私宅园林，也是中国四大名园之一，国家AAAA级旅游景区。个园占地面积约2.3公顷，以竹石取胜，园内遍植各类竹子，因竹叶形似“个”字而得名“个园”。', 'attraction', '扬州', '45元/人（旺季），30元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1183, '何园（寄啸山庄）', '扬州市广陵区徐凝门大街66号', '何园位于扬州市广陵区，始建于清光绪九年（1883年），是清代晚期建造的大型私家园林，也是国家AAAA级旅游景区。何园原名“寄啸山庄”，因园主何芷舠曾任湖北汉黄德道台，辞官归里后建此园，取陶渊明“倚南窗以寄傲，审容膝之易安”和“登东皋以舒啸，临清流而赋诗”之意，命名为“寄啸山庄”，简称“何园”。', 'attraction', '扬州', '45元/人（旺季），30元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1184, '大明寺（鉴真纪念堂）', '扬州市邗江区平山堂东路8号（瘦西湖西侧）', '大明寺位于扬州市西北郊，蜀岗中峰之上，始建于南朝宋孝武帝大明年间（457-464年），距今已有1500多年历史，是扬州最古老的寺庙之一，也是唐代高僧鉴真大师的出家地和弘法道场。大明寺因始建于大明年间而得名，清乾隆三十年（1765年）乾隆皇帝巡视扬州时，因忌讳“大明”二字，曾下令改名为“栖灵寺”，但民间仍习称“大明寺”。', 'attraction', '扬州', '45元/人（旺季），30元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1185, '东关街历史街区', '扬州市广陵区东关街（东至古运河，西至国庆路）', '东关街位于扬州市广陵区，是扬州最具代表性的历史文化街区，也是中国历史文化名街。东关街全长1122米，宽约5米，街面由长条石铺成，两侧商铺林立，保留了大量的明清建筑和民国建筑，是扬州古城风貌保存最完好的历史街区之一。', 'attraction', '扬州', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1186, '富春茶社（国庆路总店）', '扬州市广陵区国庆路125号', '富春茶社始创于清光绪十一年（1885年），是扬州最著名的百年老字号，也是淮扬菜的代表性餐厅。以淮扬细点和淮扬菜肴为主，蟹黄汤包汤汁鲜美，大煮干丝做工精细，是体验正宗淮扬美食的绝佳去处。', 'restaurant', '扬州', '80-120元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1187, '冶春茶社（御码头店）', '扬州市邗江区大虹桥路22号（御码头旁）', '冶春茶社始创于清乾隆年间，是扬州最著名的茶社之一，以淮扬细点和早茶闻名。餐厅位于瘦西湖畔，环境优雅，是体验扬州“早上皮包水”文化的最佳去处。', 'restaurant', '扬州', '70-110元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1188, '扬州炒饭（老扬州炒饭店）', '扬州市广陵区东关街128号', '扬州炒饭是扬州最具代表性的特色美食，相传起源于隋朝越国公杨素创制的“碎金饭”，相传隋炀帝巡游扬州时将“碎金饭”传入扬州，后经不断改进，成为了扬州最具代表性的美食名片。', 'restaurant', '扬州', '30-60元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1189, '三头宴（扬州大酒店）', '扬州市广陵区汶河北路50号', '三头宴是淮扬菜的代表性宴席，以扒烧整猪头、蟹粉狮子头、拆烩鲢鱼头三道大菜为主，做工精细，口味鲜美，是体验淮扬菜精髓的绝佳去处。', 'restaurant', '扬州', '100-180元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1190, '扬州小吃聚集区（东关街、彩衣街）', '扬州市广陵区东关街、彩衣街（多家小吃店）', '东关街和彩衣街是扬州最著名的小吃聚集区，汇聚了扬州各种特色小吃和老字号餐厅，是品尝扬州美食、体验扬州古城文化的绝佳去处。', 'restaurant', '扬州', '40-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1191, '扬州迎宾馆', '扬州市邗江区长春路1号（瘦西湖畔）', '国宾馆级豪华酒店，位于瘦西湖畔，环境清幽，园林式布局，客房分布在花园般的环境中，是游览瘦西湖后理想的休息之处。', 'hotel', '扬州', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1192, '扬州瘦西湖温泉度假村', '扬州市邗江区瘦西湖路18号', '五星级度假酒店，位于瘦西湖畔，拥有丰富的温泉资源，环境优美，设施豪华，是休闲度假的理想选择。', 'hotel', '扬州', '600-1500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1193, '如家酒店（扬州东关街店）', '扬州市广陵区泰州路88号', '经济型连锁酒店，位于东关街附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '扬州', '180-320元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1194, '扬州古城民宿聚集区', '扬州市广陵区东关街、仁丰里周边（多家民宿）', '古色古香的民宿聚集区，位于古城内，建筑风格古朴典雅，充满历史韵味，是体验扬州古城文化、感受江南慢生活的理想住宿选择。', 'hotel', '扬州', '200-500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1195, '扬州运河畔精品酒店', '扬州市广陵区古运河畔（多家精品酒店）', '精品设计酒店，位于古运河畔，部分客房可俯瞰古运河美景，设计融合了中国古典元素与现代风格，是体验扬州“夜运河”魅力的理想住宿选择。', 'hotel', '扬州', '400-900元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1196, '承德避暑山庄及周围寺庙景区', '承德市双桥区丽正门大街20号', '承德避暑山庄及周围寺庙景区位于承德市双桥区，是中国现存最大的古典皇家园林，也是世界文化遗产、国家AAAAA级旅游景区。避暑山庄始建于1703年（康熙四十二年），历经清康熙、雍正、乾隑三朝，耗时89年建成，占地面积564万平方米，相当于颐和园的两倍、故宫的八倍。山庄分为宫殿区和苑景区两大部分，苑景区又包括湖区、平原区、山区三部分，融南北园林艺术于一体，集中国古代造园艺术之大成。', 'attraction', '承德', '130元/人（旺季联票），90元/人（淡季联票）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1197, '普陀宗乘之庙（小布达拉宫）', '承德市双桥区环城北路近避暑山庄北侧', '普陀宗乘之庙位于承德市双桥区，避暑山庄北侧，因建筑风格酷似西藏拉萨的布达拉宫，俗称"小布达拉宫"。该庙建于清乾隆三十二年（1767年），是为庆祝乾隆皇帝六十大寿和皇太后八十大寿而建，是外八庙中规模最大的一座，占地面积22万平方米。', 'attraction', '承德', '80元/人（与避暑山庄联票优惠）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1198, '普宁寺（大佛寺）', '承德市双桥区普宁路1号（避暑山庄北侧）', '普宁寺俗称"大佛寺"，位于承德市双桥区普宁路1号，避暑山庄北侧，是外八庙中规模最大、保存最完整的一座，也是中国北方最大的佛教活动场所。该寺建于清乾隆二十年（1755年），是为纪念清军平定准噶尔叛乱、团结蒙藏少数民族而建。', 'attraction', '承德', '80元/人（与避暑山庄联票优惠）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1199, '磬锤峰国家森林公园（棒槌山）', '承德市双桥区磬锤峰路1号', '磬锤峰国家森林公园位于承德市双桥区，距离市区约10公里，是承德十大名景之一。公园内的主峰——磬锤峰，因其形状酷似棒槌（捣衣棒），俗称"棒槌山"。磬锤峰形成于300万年前，海拔596米，棒槌状岩石高约38米，上部直径15.04米，下部直径10.7米，巍然耸立于悬崖峭壁之上，令人叹为观止。', 'attraction', '承德', '50元/人（含索道），25元/人（不含索道）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1200, '木兰围场', '承德市围场满族蒙古族自治县棋盘山镇', '木兰围场位于承德市围场满族蒙古族自治县境内，始建于清康熙二十年（1681年），是清代皇家猎苑，也是世界上最大的皇家猎苑。围场总面积约1万平方公里，历史上曾是清朝皇帝举行"木兰秋狝"（秋季狩猎）的场所，先后有康熙、乾隆、嘉庆三位皇帝在此举行木兰秋狝105次，持续长达140余年。', 'attraction', '承德', '150元/人（景区联票）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1201, '承德老三羊汤馆', '承德市双桥区火神庙街18号', '老三羊汤馆是承德最有名的羊汤馆，已有50多年历史，以羊汤鲜美、烧饼酥脆而著称。羊汤选用优质羊肉和羊骨熬制数小时而成，汤色乳白，味道鲜美，营养丰富，是承德人最喜爱的早餐之一。', 'restaurant', '承德', '25-50元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1202, '承德驴打滚', '承德市双桥区丽正门大街56号（特产店）', '驴打滚是承德的传统小吃，用黄米面、黄豆面、红豆沙制成，色泽金黄，口感软糯，豆香浓郁，是承德最具代表性的特色小吃之一。此外，承德的碗坨和荞麦河漏也极具地方特色，值得一试。', 'restaurant', '承德', '10-30元/人（小吃），50-100元（伴手礼）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1203, '避暑山庄宫廷菜餐厅', '承德市双桥区山庄东路12号', '餐厅位于避暑山庄附近，主打清代宫廷菜系，选用坝上草原的优质食材，包括鹿肉、山鸡、坝上羊肉等，烹饪工艺精湛，味道鲜美，是体验清代皇家饮食文化的绝佳去处。', 'restaurant', '承德', '100-200元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1204, '围场烤全羊', '承德市围场满族蒙古族自治县木兰围场景区内', '围场烤全羊是木兰围场的特色美食，选用坝上草原放养的羔羊，用传统工艺烤制而成，外焦里嫩，鲜香四溢。搭配手把肉和奶茶，是体验蒙古族饮食文化的绝佳方式。', 'restaurant', '承德', '150-300元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1205, '承德凉粉', '承德市双桥区南营子大街32号', '承德凉粉是当地的传统小吃，用绿豆淀粉制成，口感爽滑，搭配特制的麻酱、蒜泥、醋等调料，酸辣可口，是夏季消暑的佳品。', 'restaurant', '承德', '10-25元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1206, '承德避暑山庄希尔顿欢朋酒店', '承德市双桥区迎宾路88号', '高档商务酒店，位于市区核心地段，紧邻避暑山庄，装修现代典雅，设施齐全，服务优质，是商务出行和旅游度假的理想选择。', 'hotel', '承德', '600-1200元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1207, '承德清宫酒店', '承德市双桥区山庄东路6号', '仿清代建筑风格的文化主题酒店，位于避暑山庄附近，建筑古朴素雅，充满皇家园林气息，部分客房可俯瞰山庄美景，文化氛围浓厚。', 'hotel', '承德', '400-800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1208, '如家酒店（承德火车站店）', '承德市双桥区车站路45号', '经济型连锁酒店，位于承德火车站附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '承德', '150-280元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1209, '木兰围场草原民宿', '承德市围场满族蒙古族自治县棋盘山镇', '草原特色民宿，位于木兰围场景区内，提供蒙古包住宿体验，可以品尝手把肉、奶茶等蒙古族美食，是体验草原文化的绝佳选择。', 'hotel', '承德', '150-300元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1210, '承德市双桥区民宿聚集区', '承德市双桥区丽正门大街周边', '双桥区有许多家庭式民宿，价格实惠，主人热情好客，提供家常菜和旅游咨询服务，是体验承德本地生活的经济之选。', 'hotel', '承德', '120-250元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1211, '鼋头渚景区', '无锡市滨湖区鼋渚路1号', '鼋头渚位于无锡市滨湖区太湖之滨，是太湖风景名胜区的主景点，也是国家AAAAA级旅游景区，被誉为“太湖第一名胜”“中华赏樱胜境”。鼋头渚因巨石突入湖中，状如鼋头而得名，占地面积约5.39平方公里，其中水域面积约占2/5，湖光山色美不胜收。', 'attraction', '无锡', '90元/人（旺季），70元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1212, '灵山大佛景区', '无锡市滨湖区灵山路1号', '灵山大佛景区位于无锡市滨湖区马山国家风景名胜区内，是中国著名的佛教文化主题公园，也是国家AAAAA级旅游景区。灵山大佛建于1994-1997年，佛身高88米，连同基座通高105.8米，是目前世界上最高的青铜释迦牟尼立像，由1560块青铜壁板拼装焊接而成，重约700吨，造型庄严雄伟，气势磅礴。', 'attraction', '无锡', '210元/人（成人），105元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1213, '三国城·水浒城', '无锡市滨湖区山水西路128号（三国城），无锡市滨湖区水浒城大道1号（水浒城）', '三国城·水浒城位于无锡市滨湖区太湖之滨，是中国第一家影视文化主题公园，也是国家AAAA级旅游景区。三国城建于1991-1994年，是为拍摄电视剧《三国演义》而建；水浒城建于1995-1997年，是为拍摄电视剧《水浒传》而建。两座城池隔湖相望，再现了三国时期和水浒传中的历史场景和民俗风貌。', 'attraction', '无锡', '三国城90元/人，水浒城90元/人，联票150元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1214, '蠡湖公园', '无锡市滨湖区蠡湖大道（沿湖岸线）', '蠡湖公园位于无锡市滨湖区，是环绕蠡湖而建的大型开放式景观公园，也是无锡市民休闲娱乐的主要场所之一。蠡湖是太湖伸入无锡的一条内湖，湖面面积9.1平方公里，湖岸线长约30公里，因春秋时期越国大夫范蠡携西施泛舟湖上而得名，距今已有2500多年历史。', 'attraction', '无锡', '免费开放（部分景点收费）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1215, '南长街（清名桥历史文化街区）', '无锡市梁溪区清名桥历史文化街区（南长街）', '南长街位于无锡市梁溪区，是清名桥历史文化街区的核心组成部分，也是无锡最具代表性的历史文化街区之一。南长街全长约5.5公里，沿古运河而建，保留了大量的明清建筑和民国建筑，是京杭大运河沿线保存最完好的历史文化街区之一，被誉为“运河绝版地，江南水弄堂”。', 'attraction', '无锡', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1216, '无锡酱排骨（三凤桥总店）', '无锡市梁溪区中山路240号', '三凤桥始创于1927年，是商务部首批认定的“中华老字号”餐饮企业，以无锡酱排骨为代表作，酱排骨色泽酱红，骨酥肉烂，汁浓味鲜，是无锡最具代表性的特色美食之一。', 'restaurant', '无锡', '60-100元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1217, '王兴记（中山路总店）', '无锡市梁溪区中山路216号', '王兴记始创于1913年，是商务部首批认定的“中华老字号”餐饮企业，以无锡小笼包和馄饨著称，小笼包皮薄馅大，汤汁鲜美，是体验无锡本帮小吃的首选餐厅。', 'restaurant', '无锡', '40-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1218, '清水油面筋', '无锡市梁溪区南长街（多家餐厅）', '油面筋是无锡的传统特色食品，用面粉洗出面筋后油炸而成，色泽金黄，口感筋道，是无锡人最喜爱的家常菜之一。', 'restaurant', '无锡', '30-60元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1219, '无锡馄饨（笑来喜总店）', '无锡市梁溪区健康路28号', '笑来喜始创于1998年，是无锡最有名的馄饨连锁店，以馄饨皮薄馅大、汤头鲜美而著称，是无锡最具代表性的特色小吃之一。', 'restaurant', '无锡', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1220, '太湖三白', '无锡市滨湖区鼋头渚景区周边（多家餐厅）', '太湖三白是指太湖特产的白鱼、白虾、银鱼，肉质鲜嫩，味道清甜，是太湖流域最具代表性的湖鲜美食，也是到无锡必尝的特色菜肴。', 'restaurant', '无锡', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1221, '无锡万达喜来登酒店', '无锡市滨湖区太湖大道188号', '五星级豪华酒店，位于太湖广场商务区，部分客房可俯瞰太湖美景，设施豪华，服务一流，是商务出行和高端旅游的理想选择。', 'hotel', '无锡', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1222, '无锡灵山精舍', '无锡市滨湖区灵山路5号（灵山大佛景区内）', '禅意主题精品酒店，位于灵山大佛景区内，环境清幽，充满禅意，是体验佛教文化、修身养性的理想住宿选择。', 'hotel', '无锡', '600-1500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1223, '如家酒店（无锡火车站店）', '无锡市梁溪区兴源北路818号', '经济型连锁酒店，位于无锡火车站附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '无锡', '180-320元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1224, '无锡南长街民宿', '无锡市梁溪区南长街内（多家民宿）', '古色古香的民宿聚集区，位于南长街内，建筑风格古朴典雅，充满水乡韵味，是体验无锡古城文化、感受江南水弄堂的理想住宿选择。', 'hotel', '无锡', '200-500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1225, '无锡太湖度假酒店', '无锡市滨湖区太湖国家旅游度假区内', '四星级度假酒店，位于太湖国家旅游度假区内，环境清幽，空气清新，是游览太湖后理想的休息之处。', 'hotel', '无锡', '400-900元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1226, '西湖风景名胜区', '杭州市西湖区龙井路1号（西湖风景名胜区管委会）', '西湖位于杭州市中心，是中国著名的风景游览胜地，也是世界文化遗产、国家AAAAA级旅游景区。西湖三面环山，一面临城，总面积约6.39平方公里，其中水域面积5.66平方公里，周边群山环绕，湖光山色美不胜收，被誉为"人间天堂"。', 'attraction', '杭州', '免费开放（部分景点收费，如雷峰塔40元/人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1227, '灵隐寺（云林禅寺）', '杭州市西湖区灵隐路法云弄1号', '灵隐寺位于杭州市西湖区灵隐山麓，是中国佛教禅宗名刹，也是杭州最古老的寺庙，始建于东晋咸和元年（326年），距今已有1700多年历史，相传为印度高僧慧理所建。灵隐寺历经各代修葺扩建，形成了规模宏大的寺庙建筑群，素有"东南佛国""云林禅寺"之美誉。', 'attraction', '杭州', '75元/人（含飞来峰门票），30元/人（灵隐寺香花券）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1228, '西溪国家湿地公园', '杭州市西湖区天目山路518号', '西溪国家湿地公园位于杭州市区西部，距西湖不到5公里，是中国第一个集城市湿地、农耕湿地、文化湿地于一体的国家级湿地公园，也是国家AAAAA级旅游景区。西溪湿地总面积约11.5平方公里，其中湿地面积约占70%，素有"杭州之肾""副西湖"之美誉。', 'attraction', '杭州', '80元/人（淡季），100元/人（旺季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1229, '千岛湖（新安江水库）', '杭州市淳安县千岛湖镇梦姑路348号', '千岛湖位于杭州市淳安县境内，是1959年为建设新安江水电站而筑坝蓄水形成的人工湖，因湖中拥有1078个面积大于0.25平方公里的岛屿而得名"千岛湖"。千岛湖水域面积575平方公里，蓄水量178.4亿立方米，是西湖的3000多倍，也是中国最大的人工湖之一。', 'attraction', '杭州', '150元/人（含游船）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1230, '宋城景区', '杭州市西湖区之江路148号', '宋城景区位于杭州市西湖区之江旅游度假区内，是中国最大的宋文化主题公园，也是国家AAAA级旅游景区。宋城始建于1996年，以"建筑为形，文化为魂"为设计理念，再现了宋代都城临安的繁华景象，是杭州最具特色的文化旅游景区之一。', 'attraction', '杭州', '300元/人（含《宋城千古情》演出）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1231, '楼外楼（孤山路店）', '杭州市西湖区孤山路30号', '楼外楼始创于1848年（清道光二十八年），是杭州最著名的百年老号，坐落于西湖孤山路，面临西湖，背靠孤山，环境优雅，景色宜人。以杭帮菜为主，口味清淡鲜美，是品尝正宗杭帮菜的首选餐厅。', 'restaurant', '杭州', '150-250元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1232, '知味观（湖滨店）', '杭州市上城区仁和路83号', '知味观始创于1913年，是杭州最著名的小吃店，以杭帮小吃和杭帮菜为主，小笼包皮薄馅大，汤汁鲜美，是杭州最具代表性的特色小吃之一。', 'restaurant', '杭州', '60-100元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1233, '外婆家（湖滨银泰店）', '杭州市上城区东坡路7号湖滨银泰百货4楼', '外婆家创立于1998年，是杭州本土最具影响力的餐饮品牌之一，以杭帮菜和家常菜为主，口味清淡鲜美，价格实惠，是体验杭州本地美食的绝佳去处。', 'restaurant', '杭州', '80-120元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1234, '新白鹿（延安路店）', '杭州市上城区延安路258号湖滨银泰百货B1楼', '新白鹿创立于1998年，是杭州本土知名餐饮品牌，以杭帮菜和家常菜为主，价格实惠，口味地道，是杭州最受欢迎的平价餐厅之一。', 'restaurant', '杭州', '60-90元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1235, '杭州小笼包（知味观分店）', '杭州市西湖区南山路128号（多家分店）', '杭州小笼包是杭州最具代表性的特色小吃，皮薄馅大，汤汁鲜美，是杭州人最喜爱的早餐之一。', 'restaurant', '杭州', '30-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1236, '杭州西子湖四季酒店', '杭州市西湖区灵隐路5号', '超五星级豪华酒店，位于西湖畔，环境优美，设施豪华，服务一流，是商务出行和高端旅游的理想选择。', 'hotel', '杭州', '2000-5000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1237, '杭州西湖国宾馆', '杭州市西湖区杨公堤18号', '国宾馆级豪华酒店，位于西湖畔，曾接待过多位国家领导人，环境清幽，文化氛围浓厚，是体验杭州历史文化的高端住宿选择。', 'hotel', '杭州', '1500-3000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1238, '如家酒店（杭州西湖文化广场店）', '杭州市下城区环城北路10号', '经济型连锁酒店，位于西湖文化广场附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '杭州', '200-350元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1239, '杭州青芝坞民宿聚集区', '杭州市西湖区玉古路青芝坞片区', '民宿聚集区，有数百家风格各异的民宿，价格实惠，环境清幽，是体验杭州本地生活的经济之选。', 'hotel', '杭州', '150-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1240, '杭州西湖天地精品酒店', '杭州市上城区南山路240号（西湖天地内）', '精品设计酒店，位于西湖天地内，紧邻西湖，设计融合了中国古典元素与现代风格，是体验西湖文化、感受杭州魅力的理想住宿选择。', 'hotel', '杭州', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1241, '开元寺', '泉州市鲤城区西街176号', '开元寺位于泉州市鲤城区西街，是福建规模最大的佛教寺院，也是世界文化遗产“泉州：宋元中国的世界海洋商贸中心”的重要组成部分。开元寺始建于唐垂拱二年（686年），距今已有1300多年历史，相传为黄守恭桑树开白莲而舍地建寺，初名“莲花寺”，后改名“兴教寺”“龙兴寺”，唐开元二十六年（738年）改名为“开元寺”，沿用至今。', 'attraction', '泉州', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1242, '清源山风景名胜区', '泉州市丰泽区清源山风景区', '清源山位于泉州市北郊，是泉州最具代表性的自然景观，也是国家AAAA级旅游景区。清源山因山上泉眼诸多、清泉潺潺而得名，最高峰海拔498米，山脉绵延20公里，素有“闽海蓬莱第一山”之美誉。', 'attraction', '泉州', '70元/人（成人），35元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1243, '泉州西街（西街历史文化街区）', '泉州市鲤城区西街（钟楼至城西路）', '西街位于泉州市鲤城区，是泉州最具代表性的历史文化街区，也是泉州古城的“活化石”。西街始建于唐代，距今已有1300多年历史，是泉州最古老的街道之一，素有“一条西街，半部泉州史”之美誉。', 'attraction', '泉州', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1244, '洛阳桥（万安桥）', '泉州市洛江区洛阳江入海口', '洛阳桥位于泉州市洛江区洛阳江入海口，是中国四大古桥之一，也是中国第一座跨海大石桥，始建于北宋皇祐五年（1053年），历时六年建成，距今已有近1000年历史，是全国重点文物保护单位。', 'attraction', '泉州', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1245, '崇武古城', '泉州市惠安县崇武镇', '崇武古城位于泉州市惠安县崇武半岛上，是中国现存最完整的丁字型石砌古城，也是中国海防史上保存最完好的古城之一，始建于明洪武二十年（1387年），距今已有600多年历史，是全国重点文物保护单位。', 'attraction', '泉州', '45元/人（成人），22元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1246, '好成财牛排馆（涂门街总店）', '泉州市鲤城区涂门街176号', '好成财牛排馆始创于清光绪年间，是泉州最著名的牛排专营店，以牛排汤烂而不柴、汤头鲜美醇厚而著称，是体验泉州早餐文化的绝佳去处。', 'restaurant', '泉州', '30-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1247, '斯丹姜母鸭（涂门街店）', '泉州市鲤城区涂门街221号', '斯丹姜母鸭是泉州最有名的姜母鸭专营店，创立已有30多年，以姜母鸭肉质鲜嫩、姜香浓郁、汤汁醇厚而著称，是泉州最具代表性的滋补美食之一。', 'restaurant', '泉州', '60-100元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1248, '侯阿婆肉粽（西街店）', '泉州市鲤城区西街东段（钟楼附近）', '侯阿婆肉粽是泉州最著名的小吃店，以肉粽糯而不烂、馅料丰富、蘸料独特而著称，是泉州人最喜爱的早餐和夜宵之一。', 'restaurant', '泉州', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1249, '水门国仔面线糊（水门巷总店）', '泉州市鲤城区水门巷18号', '水门国仔面线糊是泉州最著名的面线糊专营店，以面线糊细如发丝、汤头鲜美醇厚、配料丰富而著称，是泉州人最喜爱的早餐之一。', 'restaurant', '泉州', '15-30元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1250, '西街小吃聚集区', '泉州市鲤城区西街（钟楼至城西路）', '西街是泉州最著名的小吃聚集区，汇聚了泉州各种特色小吃和老字号餐厅，是品尝泉州美食、体验泉州古城文化的绝佳去处。', 'restaurant', '泉州', '40-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1251, '泉州酒店', '泉州市鲤城区庄府巷28号', '五星级豪华酒店，位于泉州古城核心地段，紧邻西街和开元寺，装修典雅豪华，设施一流，服务优质，是商务出行和高端旅游的理想选择。', 'hotel', '泉州', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1252, '泉州西湖大酒店', '泉州市丰泽区新华北路西湖公园旁', '四星级商务酒店，位于西湖公园旁，环境清幽，部分客房可俯瞰西湖美景，是商务出行和旅游度假的实惠之选。', 'hotel', '泉州', '600-1500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1253, '如家酒店（泉州西街店）', '泉州市鲤城区西街384号', '经济型连锁酒店，位于西街核心地段，购物交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '泉州', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1254, '崇武古城民宿聚集区', '泉州市惠安县崇武镇内（多家民宿）', '古城特色民宿，位于崇武古城内，建筑风格古朴典雅，充满海防文化韵味，是体验古城文化、感受惠安女风情的理想住宿选择。', 'hotel', '泉州', '150-500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1255, '泉州古城民宿聚集区', '泉州市鲤城区西街、金鱼巷周边（多家民宿）', '古色古香的民宿聚集区，位于泉州古城内，建筑风格古朴典雅，充满闽南韵味，是体验泉州古城文化、感受闽南慢生活的理想住宿选择。', 'hotel', '泉州', '180-450元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1256, '趵突泉景区', '济南市历下区趵突泉南路1号', '趵突泉位于济南市历下区，是济南七十二名泉之首，也是济南最具标志性的景观，素有“天下第一泉”之美誉，国家AAAAA级旅游景区。趵突泉因泉水喷涌如轮、三窟迸发、声若隐雷而得名，已有2700多年历史，自古就有“游济南不游趵突泉，不成游也”之说法。', 'attraction', '济南', '40元/人（旺季），20元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1257, '大明湖景区', '济南市历下区大明湖路271号', '大明湖位于济南市历下区，是济南城市名片，也是国家AAAAA级旅游景区。大明湖由城内众泉汇流而成，湖面面积约46公顷，平均水深2-3米，素有“泉城明珠”“四面荷花三面柳，一城山色半城湖”之美誉。', 'attraction', '济南', '免费开放（超然楼40元/人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1258, '千佛山（舜耕山）', '济南市历下区经十一路18号', '千佛山位于济南市南部，是济南最具代表性的自然景观，也是国家AAAA级旅游景区。千佛山因隋开皇年间（581-600年）在山上石凿佛像数千尊而得名，海拔285米，是济南“三大名胜”之一，素有“舜耕历山”“泉城之肺”之美誉。', 'attraction', '济南', '30元/人（旺季），20元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1259, '灵岩寺', '济南市长清区万德镇灵岩村', '灵岩寺位于济南市长清区，始建于东晋永兴年间（357-358年），距今已有1600多年历史，是唐代“域内四绝”之首，也是世界文化遗产（作为“长城-丝绸之路”的扩展项目）。灵岩寺因“灵岩灵验，有求必应”而得名，是济南最古老的寺庙之一。', 'attraction', '济南', '60元/人（成人），30元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1260, '解放阁', '济南市历下区黑虎泉西路2号', '解放阁位于济南市历下区黑虎泉西侧，是为纪念1948年济南战役胜利而建的阁楼，也是济南最具标志性的现代革命纪念建筑。解放阁建于1965年，1986年续建竣工，是济南“三大名胜”之外的标志性文化景观。', 'attraction', '济南', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1261, '聚丰德（经三路总店）', '济南市市中区经三路94号', '聚丰德始创于清光绪年间，是济南最著名的鲁菜老字号，以正宗鲁菜著称，糖醋鲤鱼外焦里嫩、酸甜可口，是品尝济南本帮菜的首选餐厅。', 'restaurant', '济南', '100-180元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1262, '草包包子铺（普利街总店）', '济南市历下区普利街15号', '草包包子铺始创于1937年，是济南最著名的小吃店，以猪肉灌汤包汤汁饱满、皮薄馅大著称，是济南最具代表性的特色小吃之一。', 'restaurant', '济南', '30-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1263, '孟家扒蹄（共青团路店）', '济南市历下区共青团路56号', '孟家扒蹄始创于清光绪年间，是济南最著名的卤味店，以扒蹄软烂入味、肥而不腻著称，是济南人最喜爱的下酒菜之一。', 'restaurant', '济南', '40-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1264, '油旋张（芙蓉街店）', '济南市历下区芙蓉街32号', '油旋张是济南最有名的特色小吃店，以油旋外皮酥脆、内里软糯著称，是济南最具代表性的特色小吃之一。', 'restaurant', '济南', '15-30元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1265, '济南小吃聚集区（芙蓉街、宽厚里）', '济南市历下区芙蓉街、宽厚里', '芙蓉街和宽厚里是济南最著名的小吃聚集区，汇聚了济南各种特色小吃和老字号餐厅，是品尝济南美食、体验泉城风情的绝佳去处。', 'restaurant', '济南', '50-100元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1266, '济南香格里拉大酒店', '济南市历下区泺源大街106号', '五星级豪华酒店，位于泺源大街核心地段，部分客房可俯瞰黑虎泉和护城河美景，设施豪华，服务一流，是商务出行和高端旅游的理想选择。', 'hotel', '济南', '1000-2500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1267, '济南万达凯悦酒店', '济南市市中区经四路187号', '五星级商务酒店，位于经四路核心地段，装修典雅豪华，设施一流，服务优质，是济南市标志性豪华酒店之一。', 'hotel', '济南', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1268, '如家酒店（济南趵突泉店）', '济南市历下区泺源大街98号', '经济型连锁酒店，位于趵突泉附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '济南', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1269, '济南古城民宿聚集区', '济南市历下区芙蓉街、曲水亭街周边（多家民宿）', '古色古香的民宿聚集区，位于济南古城内，建筑风格古朴典雅，充满泉城韵味，是体验济南古城文化、感受泉城慢生活的理想住宿选择。', 'hotel', '济南', '200-500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1270, '大明湖畔度假酒店', '济南市历下区大明湖路（多家度假酒店）', '度假型酒店，位于大明湖畔，环境清幽，空气清新，是游览大明湖后理想的休息之处。', 'hotel', '济南', '400-1200元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1271, '世界之窗', '深圳市南山区深南大道9037号', '世界之窗位于深圳市南山区，是中国著名的微缩景观主题公园，也是国家AAAA级旅游景区。世界之窗始建于1994年，占地面积约48万平方米，荟萃了世界奇观、历史遗迹、古今名胜、自然风光等130多个景点，被誉为“一日游遍全世界”。', 'attraction', '深圳', '220元/人（成人），110元/人（儿童/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1272, '东部华侨城', '深圳市盐田区大梅沙东部华侨城', '东部华侨城位于深圳市盐田区大梅沙，是国家级旅游度假区，也是国家AAAA级旅游景区。东部华侨城占地面积约9平方公里，集生态旅游、休闲度假、户外运动于一体，是深圳最具代表性的度假胜地。', 'attraction', '深圳', '大侠谷200元/人，茶溪谷180元/人，联票300元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1273, '莲花山公园', '深圳市福田区红荔路6030号', '莲花山公园位于深圳市中心区北端，是深圳最具标志性的城市公园，也是国家AAAA级旅游景区。莲花山公园占地面积约194公顷，主峰海拔106米，是俯瞰深圳中心区美景和市民中心的最佳位置。', 'attraction', '深圳', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1274, '深圳湾公园', '深圳市南山区深圳湾畔（沿滨海大道）', '深圳湾公园位于深圳市南山区深圳湾畔，是深圳最长的海滨生态公园，也是深圳最具代表性的城市绿洲。深圳湾公园全长约15公里，沿滨海大道而建，是深圳“拥湾发展”战略的重要生态屏障。', 'attraction', '深圳', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1275, '欢乐谷', '深圳市南山区侨城西街1号', '欢乐谷位于深圳市南山区华侨城片区，是中国著名的主题乐园连锁品牌的第一家，也是国家AAAA级旅游景区。欢乐谷始建于1998年，占地面积约35万平方米，是集欢乐、时尚、动感、梦幻于一体的现代化主题乐园。', 'attraction', '深圳', '230元/人（成人），120元/人（儿童/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1276, '深圳海鲜（东山渔村、蛇口渔港）', '深圳市南山区蛇口渔港、大鹏新区东山渔村（多家海鲜餐厅）', '深圳海鲜以新鲜、原汁原味著称，烹饪方式以清蒸、白灼、蒜蓉为主，保留了海鲜的原本鲜味，是体验深圳美食文化的绝佳去处。', 'restaurant', '深圳', '150-300元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1277, '沙井蚝（宝安沙井街道多家餐厅）', '深圳市宝安区沙井街道（多家蚝庄）', '沙井蚝是深圳最具代表性的海鲜特产，已有数百年养殖历史，蚝肉鲜嫩肥美，是深圳人最喜爱的海鲜之一。', 'restaurant', '深圳', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1278, '光明乳鸽（光明农场多家餐厅）', '深圳市光明区光明农场（多家乳鸽专营店）', '光明乳鸽是深圳最具代表性的特色美食，以皮脆肉嫩、骨肉分离而著称，是到深圳必尝的特色菜肴。', 'restaurant', '深圳', '60-120元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1279, '深圳早茶（稻香、点都德等））', '深圳市各区均有分店（如：南山区欢乐海岸店、福田区COCOPark店）', '深圳早茶是粤式饮食文化的典型代表，以精致点心、清淡口味、慢生活节奏而著称，是体验深圳“食在广东”文化的绝佳去处。', 'restaurant', '深圳', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1280, '深圳小吃聚集区（东门步行街、华强北美食街）', '深圳市罗湖区东门步行街、福田区华强北美食街', '东门步行街和华强北美食街是深圳最著名的小吃聚集区，汇聚了全国各地特色小吃和粤式甜品，是品尝深圳美食、体验深圳快节奏生活的绝佳去处。', 'restaurant', '深圳', '40-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1281, '深圳鹏瑞莱佛士酒店', '深圳市南山区中心路3008号', '超五星级豪华酒店，位于深圳湾畔，部分客房可俯瞰深圳湾和香港元朗美景，设施豪华，服务一流，是商务出行和高端旅游的理想选择。', 'hotel', '深圳', '2000-5000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1282, '深圳君悦酒店', '深圳市罗湖区宝安南路1881号', '五星级豪华酒店，位于罗湖商业中心区，紧邻东门步行街，装修典雅豪华，设施一流，服务优质，是深圳市标志性豪华酒店之一。', 'hotel', '深圳', '1500-3000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1283, '如家酒店（深圳世界之窗店）', '深圳市南山区深南大道华侨城段', '经济型连锁酒店，位于世界之窗附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '深圳', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1284, '深圳大梅沙民宿聚集区', '深圳市盐田区大梅沙片区（多家民宿）', '海滨民宿聚集区，部分民宿紧邻大梅沙海滩，可以体验渔家生活、品尝新鲜海鲜，是体验深圳海滨慢生活的理想住宿选择。', 'hotel', '深圳', '200-600元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1285, '深圳湾畔精品酒店', '深圳市南山区深圳湾畔（多家精品酒店）', '精品设计酒店，位于深圳湾畔，部分客房可俯瞰深圳湾美景和红树林湿地，设计融合了中国现代元素与海滨风情，是体验深圳“设计之都”魅力的理想住宿选择。', 'hotel', '深圳', '800-2000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1286, '蓬莱阁景区', '烟台市蓬莱区迎宾路7号', '蓬莱阁位于烟台市蓬莱区，是中国古代四大名楼之一，也是国家AAAAA级旅游景区。蓬莱阁始建于北宋嘉佑六年（1061年），由登州知州朱处约主持修建，距今已有960多年历史，素有"仙境""蓬莱仙阁"之美誉。', 'attraction', '烟台', '100元/人（成人），50元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1287, '长山列岛（庙岛群岛）', '烟台市蓬莱区长岛港区（需乘船前往）', '长山列岛位于烟台市蓬莱区以北的渤海海峡中，由32个岛屿组成，其中有居民岛屿10个，素有"海上仙山""候鸟驿站"之美誉。长岛因传说"八仙过海"在此各显神通而得名，是烟台最具代表性的海岛旅游区，也是国家AAAA级旅游景区。', 'attraction', '烟台', '长岛门票100元/人（含九丈崖、月牙湾），林海公园70元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1288, '烟台山景区', '烟台市芝罘区历新路7号', '烟台山位于烟台市芝罘区，是烟台最具标志性的景观之一，也是国家AAAA级旅游景区。烟台山原名"北山"，因明洪武三十一年（1398年）为防倭寇侵扰，在山上设狼烟墩台（烽火台）而得名"烟台山"，是烟台市名的由来。', 'attraction', '烟台', '50元/人（成人），25元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1289, '养马岛', '烟台市牟平区养马岛度假区', '养马岛位于烟台市牟平区以北的黄海之中，是一座面积约为13.5平方公里的岛屿，素有"东方夏威夷""中国第一海岛"之美誉。养马岛因相传秦始皇东巡时在此养马而得名，距今已有2200多年历史，是烟台最具代表性的海岛旅游度假区。', 'attraction', '烟台', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1290, '张裕酒文化博物馆', '烟台市芝罘区大马路56号', '张裕酒文化博物馆位于烟台市芝罘区，是中国第一座世界级葡萄酒专业博物馆，也是国家AAAA级旅游景区。张裕酒文化博物馆始建于清光绪十八年（1892年），由爱国华侨张弼士创办，是中国葡萄酒工业的发祥地，距今已有130多年历史。', 'attraction', '烟台', '60元/人（成人），30元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1291, '烟台海鲜（芝罘区滨海广场周边）', '烟台市芝罘区滨海广场周边（多家海鲜餐厅）', '烟台海鲜以新鲜、原汁原味著称，烹饪方式以清蒸、白灼、葱烧为主，保留了海鲜的原本鲜味，是体验烟台海鲜文化的绝佳去处。', 'restaurant', '烟台', '100-200元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1292, '蓬莱小面（蓬莱区钟楼南路多家店）', '烟台市蓬莱区钟楼南路（多家小面店）', '蓬莱小面是烟台最具代表性的特色小吃，用当天捕捞的海鲜和手擀面烹制而成，汤头鲜美，面条筋道，是烟台人最喜爱的早餐之一。', 'restaurant', '烟台', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1293, '张裕葡萄酒（张裕酒文化博物馆内品酒厅）', '烟台市芝罘区大马路56号（张裕酒文化博物馆内）', '张裕葡萄酒是中国最著名的葡萄酒品牌，创立于1892年，距今已有130多年历史，是品尝中国葡萄酒、了解中国葡萄酒工业发展史的首选之地。', 'restaurant', '烟台', '80-150元（品酒费用）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1294, '烟台焖子（芝罘区朝阳街多家小摊）', '烟台市芝罘区朝阳街（多家小摊）', '焖子是烟台最具代表性的特色小吃，用红薯淀粉制成，煎至外皮酥脆，内里软糯，搭配蒜泥、芝麻酱等调料，鲜香味美，是烟台人最喜爱的夜宵之一。', 'restaurant', '烟台', '15-30元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1295, '长岛海鲜（长岛县南长山岛海鲜街）', '烟台市长岛县南长山岛海鲜街（多家海鲜餐厅）', '长岛海鲜以野生小海鲜为主，肉质鲜嫩，味道鲜美，价格相对实惠，是体验长岛渔家文化、品尝地道海鲜的绝佳去处。', 'restaurant', '烟台', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1296, '烟台金海岸希尔顿酒店', '烟台市莱山区观海路1号', '五星级豪华酒店，位于莱山区海滨，部分客房可俯瞰黄海美景，设施豪华，服务一流，是商务出行和高端旅游的理想选择。', 'hotel', '烟台', '1000-2500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1297, '烟台万达艾美酒店', '烟台市芝罘区胜利路1号', '五星级商务酒店，位于芝罘区核心地段，装修现代典雅，设施一流，服务细致入微，是烟台市标志性豪华酒店之一。', 'hotel', '烟台', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1298, '如家酒店（烟台火车站店）', '烟台市芝罘区火车站前街88号', '经济型连锁酒店，位于烟台火车站附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '烟台', '180-350元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1299, '蓬莱民宿聚集区（蓬莱阁周边）', '烟台市蓬莱区蓬莱阁周边（多家民宿）', '古色古香的民宿聚集区，位于蓬莱阁周边，部分民宿可俯瞰蓬莱阁美景，是体验蓬莱仙境文化、感受古城韵味的理想住宿选择。', 'hotel', '烟台', '200-500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1300, '长岛渔家民宿（南长山岛、北长山岛）', '烟台市长岛县南长山岛、北长山岛（多家渔家民宿）', '渔家特色民宿，位于长岛各岛上，主人热情好客，提供家常海鲜餐食，可以体验渔家生活、观看黄海日出，是体验长岛慢生活的经济之选。', 'hotel', '烟台', '150-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1301, '珠海渔女景区', '珠海市香洲区情侣中路海滨浴场', '珠海渔女位于珠海市香洲区情侣中路海滨浴场，是珠海最具标志性的景观，也是珠海的城市象征。珠海渔女雕像始建于1979年，由著名雕塑家潘鹤设计，雕像高8.7米，重达10吨，是用花岗岩雕刻而成的巨型石雕，距今已有40多年历史。', 'attraction', '珠海', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1302, '长隆海洋王国', '珠海市香洲区长隆大道1号', '长隆海洋王国位于珠海市香洲区，是中国最大的海洋主题乐园之一，也是国家AAAAA级旅游景区。长隆海洋王国于2014年正式开园，占地面积约132公顷，是集海洋动物观赏、大型演艺、机动游戏于一体的综合性海洋主题乐园。', 'attraction', '珠海', '350-450元/人（根据季节浮动）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1303, '圆明新园', '珠海市香洲区九洲大道兰埔路1号', '圆明新园位于珠海市香洲区，是仿照北京圆明园部分建筑而建的园林，也是珠海最具代表性的文化主题景区，国家AAAA级旅游景区。圆明新园于1997年建成开放，占地面积约1.39平方公里，其中水域面积约0.54平方公里，是珠海最具代表性的仿古建筑群。', 'attraction', '珠海', '免费开放（部分表演收费）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1304, '东澳岛', '珠海市香洲区东澳岛（需从香洲港乘船）', '东澳岛位于珠海市香洲区以南，是珠海百岛中最具代表性的海岛之一，素有“钻石沙滩”“蜜月天堂”之美誉。东澳岛因岛东侧的东澳湾而得名，岛上有南沙湾、大竹湾、小竹湾等多处天然海滩，其中南沙湾沙滩是珠海最美的沙滩之一。', 'attraction', '珠海', '免费开放（部分景点收费，如蜜月阁30元/人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1305, '斗门古街（斗门旧街）', '珠海市斗门区斗门镇', '斗门古街位于珠海市斗门区斗门镇，是珠海最具代表性的历史文化街区，也是珠海保存最完好的古街区之一。斗门古街始建于清代，距今已有200多年历史，素有“珠海历史活化石”之美誉。', 'attraction', '珠海', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1306, '珠海海鲜（湾仔海鲜街）', '珠海市香洲区湾仔街道海鲜街（多家海鲜餐厅）', '湾仔海鲜街是珠海最有名的海鲜聚集地，沿湾仔海岸而建，海鲜均来自南海当日捕捞，新鲜味美，是品尝珠海海鲜的绝佳去处。', 'restaurant', '珠海', '150-250元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1307, '珠海渔家菜（横琴镇多家餐厅）', '珠海市香洲区横琴镇（多家渔家菜餐厅）', '横琴镇是珠海渔家菜最集中的地方，以新鲜渔家食材和传统烹饪方式为主，口味鲜美，是体验珠海渔家文化的绝佳去处。', 'restaurant', '珠海', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1308, '珠海乳鸽（斗门名鸽养殖场）', '珠海市斗门区井岸镇（多家乳鸽餐厅）', '乳鸽是珠海最具代表性的特色美食，肉质鲜嫩，骨肉分离，是珠海人最喜爱的家常菜之一。', 'restaurant', '珠海', '60-120元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1309, '珠海小吃聚集区（拱北口岸商业街）', '珠海市香洲区拱北口岸商业街', '拱北口岸商业街是珠海最著名的小吃聚集区，汇聚了珠海各种特色小吃和粤式美食，是品尝珠海美食、体验珠海夜生活的绝佳去处。', 'restaurant', '珠海', '40-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1310, '澳门街（珠海拱北店）', '珠海市香洲区拱北口岸广场', '澳门街是珠海最具特色的葡式菜肴餐厅，以葡式蛋挞和猪脚姜为代表作，口味独特，是体验中葡文化交融的绝佳去处。', 'restaurant', '珠海', '100-180元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1311, '珠海仁恒洲际酒店', '珠海市香洲区情侣北路1号', '超五星级豪华酒店，位于情侣北路，部分客房可俯瞰珠海湾和澳门夜景，设施豪华，服务一流，是商务出行和高端旅游的理想选择。', 'hotel', '珠海', '1500-3500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1312, '珠海长隆马戏酒店', '珠海市香洲区长隆大道1号（长隆度假区内）', '五星级主题酒店，位于长隆旅游度假区内，装修充满马戏团风格，设施一流，服务细致入微，是亲子游的理想选择。', 'hotel', '珠海', '1000-2500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1313, '如家酒店（珠海拱北口岸店）', '珠海市香洲区拱北口岸广场南侧', '经济型连锁酒店，位于拱北口岸附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '珠海', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1314, '东澳岛民宿聚集区', '珠海市香洲区东澳岛（多家民宿）', '海岛特色民宿，位于东澳岛上，部分民宿紧邻海滩，可以体验渔家生活、品尝新鲜海鲜，是体验海岛慢生活的理想住宿选择。', 'hotel', '珠海', '200-600元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1315, '珠海情侣路精品酒店', '珠海市香洲区情侣中路（多家精品酒店）', '精品设计酒店，位于情侣路畔，部分客房可俯瞰珠海湾美景和澳门夜景，设计融合了中国滨海元素与现代风格，是体验珠海“浪漫之城”魅力的理想住宿选择。', 'hotel', '珠海', '400-1000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1316, '三坊七巷历史文化街区', '福州市鼓楼区南后街（杨桥东路至吉庇路）', '三坊七巷位于福州市鼓楼区，是福州最具标志性的历史文化街区，也是国家AAAAA级旅游景区。三坊七巷始建于西晋（280-316年），距今已有1700多年历史，是以纵贯南北的南后街为中轴线，西侧成片的三个坊（衣锦坊、文儒坊、光禄坊）和东侧成片的七条巷（杨桥巷、郎官巷、塔巷、黄巷、安民巷、宫巷、吉庇巷）组成的古代城市里坊群落，被誉为"明清建筑博物馆""中国城市里坊制度的活化石"。', 'attraction', '福州', '三坊七巷免费开放，个别故居如严复故居15元/人、水榭戏台20元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1317, '鼓山风景名胜区', '福州市晋安区鼓山路1号', '鼓山位于福州市东郊，是福州最具标志性的自然景观，也是国家AAAA级旅游景区。鼓山因山顶有巨石如鼓，传说风雨冲击时声如鼓鸣而得名，最高点海拔998米，是福州的"镇市之山"。鼓山佛教文化历史悠久，山上的涌泉寺始建于五代后梁乾化五年（915年），距今已有1100多年历史，是福州最古老的寺庙之一。', 'attraction', '福州', '鼓山免费开放，涌泉寺40元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1318, '福州西湖公园', '福州市鼓楼区湖滨路71号', '福州西湖位于福州市鼓楼区，是福建最古老的古典园林，始建于西晋太康三年（282年），距今已有1700多年历史，素有"福建西湖""八闽名胜"之美誉。福州西湖虽不及杭州西湖宽阔，但玲珑别致，曲径通幽，是福州最具代表性的城市绿洲。', 'attraction', '福州', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1319, '福州国家森林公园（福州植物园）', '福州市晋安区新店镇赤桥村', '福州国家森林公园位于福州市北郊，是福建省首家国家级森林公园，也是全国十大森林公园之一，占地面积约859.33公顷。森林公园始建于1960年，至今已有60多年历史，园内古木参天，树种繁多，是福州的"城市绿肺"。', 'attraction', '福州', '免费开放（需提前预约）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1320, '平潭岛（海坛岛）', '福州市平潭县潭城镇', '平潭岛位于福州市平潭县境内，是福建第一大岛，也是中国第五大岛，素有"千礁岛县""东海麒麟"之美誉。平潭岛因"沙白、水净、天蓝、石奇"而闻名，是福州最具代表性的海岛旅游胜地，也是大陆距离台湾本岛最近的地方（仅68海里）。', 'attraction', '福州', '免费开放（部分景点如石牌洋40元/人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1321, '同利肉燕老铺（三坊七巷店）', '福州市鼓楼区南后街98号', '同利肉燕始创于清光绪二年（1876年），是福州最著名的百年老号，以福州传统小吃肉燕为代表作，皮薄如纸，馅鲜味美，是福州最具代表性的特色小吃之一。', 'restaurant', '福州', '30-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1322, '永和鱼丸（南后街总店）', '福州市鼓楼区南后街122号', '永和鱼丸始创于1934年，是福州最著名的鱼丸专营店，鱼丸外皮Q弹，内馅鲜美，是福州人最喜爱的传统小吃之一。', 'restaurant', '福州', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1323, '福州捞化（台江老药洲店）', '福州市台江区老药洲街32号', '捞化是福州最具代表性的特色小吃，用极细的米粉焯熟后，配以各种海鲜、内脏、蔬菜等，汤头鲜美，米粉滑爽，是福州人最喜爱的早餐和夜宵之一。', 'restaurant', '福州', '25-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1324, '聚春园大酒店（东街口总店）', '福州市鼓楼区东街2号', '聚春园始创于清同治四年（1865年），是商务部首批认定的"中华老字号"餐饮企业，以福州首席名菜"佛跳墙"而闻名遐迩，是品尝正宗闽菜的首选餐厅。', 'restaurant', '福州', '150-300元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1325, '福州小吃聚集区（三坊七巷、台江老药洲）', '福州市鼓楼区南后街、台江区老药洲街', '三坊七巷和台江老药洲是福州最著名的小吃聚集区，汇聚了福州各种特色小吃和老字号餐厅，是品尝福州美食、体验闽都风情的绝佳去处。', 'restaurant', '福州', '40-80元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1326, '福州融侨水乡酒店', '福州市仓山区浦上大道1号', '五星级豪华酒店，位于浦上大道，紧邻乌龙江，装修典雅豪华，设施一流，服务优质，是商务出行和高端旅游的理想选择。', 'hotel', '福州', '1000-2500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1327, '福州西湖大酒店', '福州市鼓楼区湖滨路158号', '五星级商务酒店，位于西湖公园旁，环境清幽，部分客房可俯瞰西湖美景，设施豪华，服务一流，是福州市标志性豪华酒店之一。', 'hotel', '福州', '600-1500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1328, '如家酒店（福州三坊七巷店）', '福州市鼓楼区南后街入口处', '经济型连锁酒店，位于三坊七巷附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '福州', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1329, '平潭岛民宿聚集区', '福州市平潭县北港村、长江澳周边（多家民宿）', '海岛特色民宿，位于平潭岛内，部分民宿紧邻海滩，可以体验渔家生活、品尝新鲜海鲜，是体验海岛慢生活的理想住宿选择。', 'hotel', '福州', '200-600元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1330, '福州三坊七巷民宿', '福州市鼓楼区三坊七巷内（多家民宿）', '古色古香的民宿，位于三坊七巷内，建筑风格古朴典雅，充满闽都韵味，是体验福州古城文化、感受闽都风情的理想住宿选择。', 'hotel', '福州', '180-450元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1331, '山海关景区', '秦皇岛市山海关区天下第一关路1号', '山海关，又称"天下第一关"，位于秦皇岛市山海关区，是明长城的东北起点，与嘉峪关遥相呼应，被誉为"两京锁钥无双地，万里长城第一关"。山海关建于明洪武十四年（1381年），由开国名将徐达主持修建，是一座土筑砖包的雄伟关城。关城周长约4公里，与长城相连，以城为关，形成了一套完整的防御体系。', 'attraction', '秦皇岛', '50元/人（成人），25元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1332, '老龙头景区', '秦皇岛市山海关区老龙头路1号（城南5公里处渤海之滨）', '老龙头位于秦皇岛市山海关区城南5公里的渤海之滨，是明长城的东起点，也是万里长城唯一集山、海、关、城于一体的海陆军事防御体系。长城像一条巨龙，横亘在华夏大地之上，东端在山海关城南直插入海，犹如巨龙探海，因此称之为"老龙头"。', 'attraction', '秦皇岛', '60元/人（成人），30元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1333, '北戴河海滨风景区', '秦皇岛市北戴河区东海滩路', '北戴河海滨风景区位于秦皇岛市北戴河区，是中国最著名的海滨度假胜地之一，与庐山、莫干山、鸡公山并称为"中国四大避暑胜地"。北戴河因戴河自北向南流入渤海，且早期有戴姓聚居而得名，自1898年被清政府辟为"允中外人士杂居"的避暑区以来，已有120多年的开发历史。', 'attraction', '秦皇岛', '免费开放（部分景点收费）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1334, '鸽子窝公园', '秦皇岛市北戴河区东山街道鸽赤路25号', '鸽子窝公园又名"鹰角公园"，位于北戴河海滨的东北角，是北戴河风景名胜区四大景区之一，也是北戴河看日出的最佳地点。公园占地300余亩，因公园内有一块高约20米的巨石，石质坚硬，状似雄鹰，名为"鹰角石"，成群成群鸽子在此筑巢栖息，因此得名"鸽子窝"。', 'attraction', '秦皇岛', '25元/人（成人），12元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1335, '秦皇岛野生动物园', '秦皇岛市北戴河区滨海大道62号', '秦皇岛野生动物园位于秦皇岛市北戴河区滨海大道62号，坐落于美丽的渤海之滨，占地面积5000余亩，是中国较大的野生动物园之一。动物园采用大圈散养的方式，模拟野生动物的自然生存环境，让游客能够近距离观察和接触各种珍稀野生动物。', 'attraction', '秦皇岛', '100元/人（成人），50元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1336, '北戴河海鲜大排档', '秦皇岛市北戴河区联峰北路88号', '北戴河海鲜大排档是秦皇岛最著名的海鲜聚集地之一，位于北戴河区联峰北路，紧邻海滨浴场。这里汇集了数十家海鲜餐厅，提供最新鲜的海鲜食材，包括烤生蚝、蒜蓉扇贝、清蒸螃蟹、红烧海鱼等多种做法。海鲜均来自渤海湾当日捕捞，新鲜美味，价格相对实惠，是到秦皇岛旅游不可错过的美食体验。', 'restaurant', '秦皇岛', '80-150元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1337, '山海关四条包子铺', '秦皇岛市山海关区天下第一关路18号', '四条包子铺是山海关地区的老字号小吃店，始创于1958年，因店铺位于山海关四条街而得名。四条包子以皮薄馅大、鲜香味美而闻名，馅料选用上等猪肉，加入秘制调料，口感鲜嫩多汁。除了包子，店内的羊汤和烧麦也深受食客喜爱，是体验山海关地方特色小吃的绝佳去处。', 'restaurant', '秦皇岛', '20-40元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1338, '秦皇岛烤肉季', '秦皇岛市海港区文化路156号', '烤肉季是秦皇岛本地非常有名的烧烤店，成立于1990年代，以炭火慢烤、肉质鲜嫩著称。餐厅选用优质的羊肉、牛肉和海鲜，配以秘制调料，炭火慢烤而成，外焦里嫩，鲜香四溢。尤其推荐烤羊排和烤生蚝，是秦皇岛夏夜消暑纳凉、朋友聚餐的理想选择。', 'restaurant', '秦皇岛', '60-100元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1339, '老二位麻酱烧饼', '秦皇岛市海港区河北大街中段102号', '老二位麻酱烧饼是秦皇岛的传统小吃，已有70多年历史，因店铺最早由两位老人创办而得名。麻酱烧饼外皮酥脆，内里松软，麻酱香气浓郁，甜咸适中，是秦皇岛人最喜爱的早餐之一。搭配一碗热腾腾的豆腐脑或豆浆，是体验秦皇岛本地生活的绝佳方式。', 'restaurant', '秦皇岛', '10-20元/人', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1340, '北戴河杨肠子火腿肠', '秦皇岛市北戴河区草厂西路12号（特产店）', '杨肠子火腿肠是秦皇岛北戴河的特色食品，始创于1942年，由北戴河杨氏家族创制，采用传统工艺和秘方制成，肉质紧实，鲜香味美，是北戴河最具代表性的伴手礼之一。除了火腿肠，北戴河还有丰富的海鲜干货，如干贝、海参、虾米等，是馈赠亲友的佳品。', 'restaurant', '秦皇岛', '30-80元（购买伴手礼）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1341, '秦皇岛香格里拉大酒店', '秦皇岛市海港区河滨路123号', '五星级豪华酒店，位于海港核心区，紧邻渤海，部分客房可俯瞰海景，设施豪华，服务一流，适合高端商务及度假旅客。', 'hotel', '秦皇岛', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1342, '北戴河悦华酒店', '秦皇岛市北戴河区东海滩路6号', '四星级度假酒店，位于北戴河海滨，步行可达海滩，环境优美，空气清新，是避暑度假的理想选择。', 'hotel', '秦皇岛', '500-1200元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1343, '如家酒店（秦皇岛火车站店）', '秦皇岛市海港区迎宾路56号', '经济型连锁酒店，位于秦皇岛火车站附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '秦皇岛', '180-300元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1344, '山海关古城客栈', '秦皇岛市山海关区天下第一关路68号', '古色古香的主题客栈，位于山海关古城内，建筑风格古朴素雅，充满历史韵味，是体验古城文化的最佳住宿选择。', 'hotel', '秦皇岛', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1345, '北戴河民宿聚集区（刘庄民宿）', '秦皇岛市北戴河区刘庄片区', '北戴河刘庄是著名的民宿聚集区，有数百家家庭式民宿，价格实惠，主人热情好客，提供家常海鲜餐食，是体验本地生活的经济之选。', 'hotel', '秦皇岛', '100-250元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1346, '普陀山风景名胜区', '舟山市普陀区普陀山岛', '普陀山位于舟山市普陀区，是舟山群岛中的一个小岛，与山西五台山、四川峨眉山、安徽九华山并称为中国佛教四大名山，也是观音菩萨的根本道场，素有"海天佛国""南海圣境"之美誉，国家AAAAA级旅游景区。普陀山占地面积约12.5平方公里，素有"第一人间清净地"之美誉。', 'attraction', '舟山', '160元/人（旺季），140元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1347, '嵊泗列岛风景名胜区', '舟山市嵊泗县嵊泗列岛', '嵊泗列岛位于舟山市北部，是国家级风景名胜区，由404个岛屿组成，其中有人居住的岛屿16个，素有"东海蓬莱""碧海奇礁，金沙渔火"之美誉。嵊泗列岛海域面积8747平方公里，其中陆域面积86平方公里，是舟山最具代表性的海岛旅游度假区。', 'attraction', '舟山', '免费开放（部分景点收费，如基湖沙滩40元/人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1348, '桃花岛风景名胜区', '舟山市普陀区桃花岛', '桃花岛位于舟山市普陀区，是舟山群岛中的第七大岛，因金庸先生的武侠小说《射雕英雄传》和《神雕侠侣》而闻名遐迩，素有"海山仙子国""东方琅環"之美誉。桃花岛占地面积约40.37平方公里，是舟山最具武侠文化特色的旅游岛屿。', 'attraction', '舟山', '免费开放（部分景点收费，如桃花寨30元/人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1349, '东极岛', '舟山市普陀区东极镇', '东极岛位于舟山市普陀区东极镇，是中国最东面的住人岛屿，由庙子湖岛、青浜岛、东福山岛、黄兴岛等28个岛屿组成，素有"东极之东""东海极地"之美誉。东极岛因2013年韩寒导演的电影《后会无期》在此取景而名声大噪，成为了年轻人向往的"远方"和"诗"的代名词。', 'attraction', '舟山', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1350, '朱家尖', '舟山市普陀区朱家尖岛', '朱家尖位于舟山市普陀区，与普陀山隔海相望，是舟山群岛中的第五大岛，素有"沙雕故乡""东方夏威夷"之美誉。朱家尖占地面积约72平方公里，以沙雕艺术、海滨浴场、佛教文化而著称，是舟山最具活力的旅游岛屿之一。', 'attraction', '舟山', '免费开放（南沙景点旺季70元/人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1351, '沈家门海鲜夜排档（总店）', '舟山市普陀区沈家门滨港路198号', '沈家门海鲜夜排档是舟山最有名的海鲜聚集地，已有30多年历史，沿沈家门渔港而建，灯火辉煌，是品尝舟山海鲜的绝佳去处。', 'restaurant', '舟山', '150-250元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1352, '舟山海鲜面（各早餐店均有）', '舟山市定海区、普陀区各早餐店', '海鲜面是舟山最具代表性的特色小吃，用当天捕捞的新鲜海鲜和手擀面烹制而成，汤头鲜美，面条筋道，是舟山人最喜爱的早餐之一。', 'restaurant', '舟山', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1353, '嵊泗海鲜（菜园镇海鲜街）', '舟山市嵊泗县菜园镇海滨路（多家海鲜餐厅）', '嵊泗海鲜以新鲜、原汁原味著称，烹饪方式以清蒸、白灼、葱油为主，保留了海鲜的原本鲜味，是体验舟山海鲜文化的绝佳去处。', 'restaurant', '舟山', '100-200元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1354, '东极岛海鲜（庙子湖岛海鲜街）', '舟山市普陀区东极镇庙子湖岛（多家海鲜餐厅）', '东极岛海鲜以野生小海鲜为主，肉质鲜嫩，味道鲜美，价格相对实惠，是体验东极岛渔家文化、品尝地道海鲜的绝佳去处。', 'restaurant', '舟山', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1355, '朱家尖海鲜（南沙海鲜大排档）', '舟山市普陀区朱家尖岛南沙景区周边（多家大排档）', '朱家尖海鲜大排档是舟山最具特色的海鲜夜宵聚集地，傍晚时分开始营业，海鲜新鲜，价格实惠，是体验朱家尖夜生活的绝佳去处。', 'restaurant', '舟山', '60-120元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1356, '舟山喜来登绿城酒店', '舟山市定海区千岛路188号', '五星级豪华酒店，位于定海城区，紧邻千岛海景，装修典雅豪华，设施一流，服务优质，是商务出行和高端旅游的理想选择。', 'hotel', '舟山', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1357, '普陀山雷迪森庄园', '舟山市普陀区普陀山岛法雨路28号', '精品禅意酒店，位于普陀山岛上，环境清幽，充满佛教文化气息，是体验普陀山佛教文化、修身养性的理想住宿选择。', 'hotel', '舟山', '600-1500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1358, '如家酒店（舟山沈家门店）', '舟山市普陀区沈家门滨港路128号', '经济型连锁酒店，位于沈家门渔港附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '舟山', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1359, '嵊泗民宿聚集区（菜园镇、基湖村）', '舟山市嵊泗县菜园镇、基湖村（多家民宿）', '海岛特色民宿，位于嵊泗列岛内，部分民宿紧邻海滩，可以体验渔家生活、品尝新鲜海鲜，是体验海岛慢生活的理想住宿选择。', 'hotel', '舟山', '150-500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1360, '东极岛渔家民宿（庙子湖岛、东福山岛）', '舟山市普陀区东极镇庙子湖岛、东福山岛（多家渔家民宿）', '渔家特色民宿，位于东极岛各岛上，主人热情好客，提供家常海鲜餐食，可以体验渔家生活、观看东海日出，是体验东极岛慢生活的经济之选。', 'hotel', '舟山', '100-300元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1361, '拙政园', '苏州市姑苏区东北街178号', '拙政园位于苏州市姑苏区，是苏州古典园林中面积最大的古典山水园林，也是中国四大名园之一，世界文化遗产。拙政园始建于明正德初年（16世纪初），距今已有500多年历史，由明代御史王献臣弃官回乡后兴建，取晋代潘岳《闲居赋》中"拙者之为政也"之意，命名为"拙政园"。', 'attraction', '苏州', '90元/人（旺季），70元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1362, '虎丘', '苏州市姑苏区虎丘山门内8号', '虎丘位于苏州市姑苏区，是苏州的城市象征，素有"吴中第一名胜""到苏州不游虎丘，乃憾事也"之美誉。虎丘海拔仅34.3米，但山体由千万年风雨侵蚀形成的独特岩石地貌，怪石嶙峋，气势不凡。虎丘始建于春秋时期，距今已有2500多年历史，是苏州历史文化的重要见证。', 'attraction', '苏州', '70元/人（旺季），60元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1363, '周庄古镇', '苏州市昆山市周庄镇全福路43号', '周庄古镇位于苏州市昆山市最南端，是中国第一水乡，也是江南六大古镇之首，始建于北宋元祐元年（1086年），距今已有930多年历史。周庄古镇保存有大量的明清建筑，古桥、古街、古宅、古巷错落有致，有水贯镇而过，形成了"井"字形的河道格局，居民依水而筑，粉墙黛瓦，小桥流水，如诗如画。', 'attraction', '苏州', '100元/人（日游），80元/人（夜游）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1364, '寒山寺', '苏州市姑苏区寒山寺弄24号', '寒山寺位于苏州市姑苏区，始建于南朝萧梁天监年间（502-519年），距今已有1500多年历史，是中国著名的禅宗寺院，也是苏州最古老的寺庙之一。寒山寺因唐代诗人张继的七绝《枫桥夜泊》而闻名遐迩，诗中"姑苏城外寒山寺，夜半钟声到客船"成为千古绝唱，使寒山寺成为中国文化史上的重要符号。', 'attraction', '苏州', '20元/人（成人），10元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1365, '金鸡湖景区', '苏州市吴中区星港街（金鸡湖西岸）', '金鸡湖景区位于苏州市吴中区（苏州工业园区内），是苏州最著名的现代旅游景区之一，也是开放式的国家AAAAA级旅游景区。金鸡湖水域面积7.4平方公里，比杭州西湖大1.87平方公里，湖畔建有现代化的商业街区、文化艺术中心、摩天轮、音乐喷泉等景观和设施，是苏州现代化都市风貌的典型代表。', 'attraction', '苏州', '免费开放（部分景点收费）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1366, '松鹤楼（观前街店）', '苏州市姑苏区观前街太监弄72号', '松鹤楼始创于清乾隆二十二年（1757年），是苏州最古老的苏帮菜馆，也是商务部首批认定的"中华老字号"餐饮企业。以松鼠鳜鱼为代表的苏帮菜肴做工精细，口味清淡鲜美，是体验正宗苏帮菜的首选餐厅。', 'restaurant', '苏州', '150-250元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1367, '得月楼（李公堤店）', '苏州市吴中区金鸡湖大道李公堤2号', '得月楼始创于明嘉靖年间，是苏州最著名的苏帮菜馆之一，以正宗苏帮菜和精致的就餐环境而著称，是品尝苏州本帮菜、体验苏州饮食文化的绝佳去处。', 'restaurant', '苏州', '120-200元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1368, '朱鸿兴面馆（观前街店）', '苏州市姑苏区观前街宫巷63号', '朱鸿兴面馆始创于1938年，是苏州最著名的面馆，以苏式汤面著称，面条细滑筋道，汤头鲜美醇厚，是体验苏州早餐文化的绝佳去处。', 'restaurant', '苏州', '30-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1369, '采芝斋（观前街总店）', '苏州市姑苏区观前街91号', '采芝斋始创于清光绪十年（1884年），是苏州最著名的老字号糖果店，以苏式糖果和糕点闻名，是苏州最具代表性的伴手礼之一。', 'restaurant', '苏州', '30-80元（购买伴手礼）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1370, '黄天源（观前街总店）', '苏州市姑苏区观前街86号', '黄天源始创于清道光元年（1821年），是苏州最著名的糕团店，以苏式糕团闻名，糕团软糯香甜，口感细腻，是苏州最具代表性的特色小吃之一。', 'restaurant', '苏州', '20-40元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1371, '苏州凯悦酒店', '苏州市姑苏区华池街88号', '五星级豪华酒店，位于金鸡湖东岸，部分客房可俯瞰金鸡湖美景，设施豪华，服务一流，是商务出行和高端旅游的理想选择。', 'hotel', '苏州', '1200-2500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1372, '苏州南园宾馆', '苏州市姑苏区带城桥路99号', '国宾馆级豪华酒店，位于南园遗址之上，环境清幽，文化氛围浓厚，是体验苏州古典园林文化的理想住宿选择。', 'hotel', '苏州', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1373, '如家酒店（苏州观前街店）', '苏州市姑苏区观前街碧凤坊38号', '经济型连锁酒店，位于观前街核心地段，购物交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '苏州', '200-350元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1374, '周庄古镇民宿', '苏州市昆山市周庄镇内（多家民宿）', '古色古香的古镇民宿，位于周庄古镇内，建筑风格古朴典雅，充满水乡韵味，是体验古镇慢生活的理想住宿选择。', 'hotel', '苏州', '200-500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1375, '苏州古城区民宿聚集区', '苏州市姑苏区平江路、山塘街周边', '古城区有大量的家庭式民宿，价格实惠，主人热情好客，提供家常菜和旅游咨询服务，是体验苏州本地生活的经济之选。', 'hotel', '苏州', '150-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1376, '崂山风景名胜区', '青岛市崂山区崂山路1号', '崂山位于青岛市崂山区，是中国海岸线第一高峰，也是国家AAAAA级旅游景区。崂山主峰“巨峰”海拔1132.7米，山体以花岗岩为主，素有“海上名山第一”“神仙之宅”“灵异之府”之美誉，是中国海岸线最高的山峰。', 'attraction', '青岛', '130元/人（旺季），100元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1377, '八大关风景区', '青岛市市南区汇泉角八大关景区', '八大关位于青岛市市南区汇泉角，是青岛最具代表性的历史文化街区，也是中国著名的风景疗养区，素有“万国建筑博览会”“东方瑞士”之美誉。八大关因有八条以中国著名关隘命名的大路（山海关、嘉峪关、武胜关、宁武关、居庸关、韶关、函谷关、正阳关）而得名，实际共有十条以关隘命名的道路。', 'attraction', '青岛', '免费开放（部分景点收费，如花石楼10元/人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1378, '栈桥景区', '青岛市市南区太平路14号', '栈桥位于青岛市市南区，是青岛的象征性建筑，也是青岛最具标志性的景观之一。栈桥始建于清光绪十七年（1891年），距今已有130多年历史，是青岛最早的军事专用码头，也是青岛近代历史的重要见证。', 'attraction', '青岛', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1379, '金沙滩景区', '青岛市黄岛区金沙滩路1号', '金沙滩位于青岛市黄岛区，是青岛最具代表性的海滨浴场，也是中国最美丽的沙滩之一，素有“亚洲第一滩”之美誉。金沙滩全长3500多米，宽约300米，因沙质细腻柔软、色泽如金而得名“金沙滩”。', 'attraction', '青岛', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1380, '青岛啤酒博物馆', '青岛市市北区登州路56号', '青岛啤酒博物馆位于青岛市市北区登州路56号，是青岛啤酒厂百年老厂房遗址上改建而成的专业啤酒博物馆，也是国家AAAA级旅游景区。青岛啤酒博物馆始建于1903年（清光绪二十九年），由英德商人合资兴建，距今已有120多年历史，是青岛啤酒工业文化的见证。', 'attraction', '青岛', '60元/人（成人），30元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1381, '青岛海鲜（营口路市场）', '青岛市市北区营口路市场（多家海鲜加工店）', '营口路市场是青岛最有名的海鲜聚集地，游客可以在市场内选购新鲜海鲜，然后拿到附近的加工店进行烹饪，经济实惠，是体验青岛海鲜文化的绝佳去处。', 'restaurant', '青岛', '100-200元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1382, '鲅鱼水饺（船歌鱼水饺总店）', '青岛市市南区闽江路156号', '船歌鱼水饺是青岛最有名的水饺专营店，创立于2004年，以鲅鱼水饺为代表作，皮薄馅大，汤汁鲜美，是体验青岛面食文化的绝佳去处。', 'restaurant', '青岛', '60-100元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1383, '青岛锅贴（沧口锅贴总店）', '青岛市李沧区沧口广场18号', '沧口锅贴是青岛的传统小吃，创立已有50多年历史，以锅贴底脆馅鲜、汤汁饱满而著称，是青岛人最喜爱的早餐之一。', 'restaurant', '青岛', '30-60元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1384, '青岛烧烤（台东步行街多家店）', '青岛市市北区台东三路步行街（多家烧烤店）', '台东步行街是青岛最著名的烧烤聚集地，沿途有数十家海鲜烧烤店，烤鱿鱼鲜香扑鼻，是青岛人最喜爱的夜宵之一。', 'restaurant', '青岛', '60-120元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1385, '青岛啤酒（啤酒博物馆内餐厅）', '青岛市市北区登州路56号（青岛啤酒博物馆内）', '青岛啤酒博物馆内的餐厅是品尝最新鲜青岛啤酒的绝佳去处，啤酒直接从生产线下来，鲜香冰爽，是体验青岛啤酒文化的首选之地。', 'restaurant', '青岛', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1386, '青岛海尔洲际酒店', '青岛市市南区澳门路98号', '超五星级豪华酒店，位于奥帆中心核心地段，部分客房可俯瞰浮山湾和五四广场美景，设施豪华，服务一流，是商务出行和高端旅游的理想选择。', 'hotel', '青岛', '1500-3500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1387, '青岛海景花园大酒店', '青岛市市南区东海中路11号', '五星级商务酒店，位于海滨步行街核心地段，紧邻第一海水浴场，装修典雅豪华，设施一流，服务优质，是青岛市标志性豪华酒店之一。', 'hotel', '青岛', '800-1800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1388, '如家酒店（青岛栈桥店）', '青岛市市南区太平路18号', '经济型连锁酒店，位于栈桥附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '青岛', '200-400元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1389, '青岛八大关民宿聚集区', '青岛市市南区八大关景区内（多家民宿）', '历史建筑改建的民宿聚集区，位于八大关景区内，建筑风格各异，充满历史韵味，是体验青岛古城文化、感受万国建筑博览会的理想住宿选择。', 'hotel', '青岛', '300-800元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1390, '青岛黄岛金沙滩度假酒店', '青岛市黄岛区金沙滩路1号', '四星级度假酒店，位于金沙滩畔，环境清幽，空气清新，是游览金沙滩后理想的休息之处。', 'hotel', '青岛', '600-1500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1391, '黄山风景区', '黄山市黄山区汤口镇黄山风景区管理处', '黄山风景区位于黄山市境内，是中国十大名山之一，也是世界文化与自然双重遗产、国家AAAAA级旅游景区。黄山古称"黔山"，因传说黄帝在此炼丹升天而改名为"黄山"，素有"天下第一奇山""五岳归来不看山，黄山归来不看岳"之美誉。', 'attraction', '黄山', '190元/人（旺季），150元/人（淡季）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1392, '宏村景区', '黄山市黟县宏村镇宏村景区', '宏村位于黄山市黟县东北部，是古黟桃花源里一座奇特的牛形古村落，也是世界文化遗产、国家AAAA级旅游景区。宏村始建于南宋绍兴元年（1131年），距今已有890多年历史，因"扩而成太乙象，故而美曰弘村"，清乾隆年间更名为宏村。', 'attraction', '黄山', '104元/人（成人），52元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1393, '西递景区', '黄山市黟县西递镇西递村', '西递位于黄山市黟县东部，是徽州古村落的典型代表，也是世界文化遗产、国家AAAA级旅游景区。西递始建于北宋庆历七年（1047年），距今已有970多年历史，因村边有水西流，又因古有递送邮件的驿站，故得名"西递"。', 'attraction', '黄山', '104元/人（成人），52元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1394, '屯溪老街', '黄山市屯溪区老街（屯溪老街历史文化街区）', '屯溪老街位于黄山市中心城区，是一条保存完好的宋代商业长街，也是中国保存最完整、最具有南宋和明清建筑风格的古代街市，素有"活着的清明上河图""中国第一条历史文化街区"之美誉。', 'attraction', '黄山', '免费开放', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1395, '唐模景区', '黄山市徽州区潜口镇唐模村', '唐模位于黄山市徽州区，是徽州古村落之一，也是国家AAAA级旅游景区。唐模始建于唐代，距今已有1100多年历史，因大唐模范村而得名"唐模"，又因村中有一条小溪穿村而过，形似一条龙，故又名"龙川"。', 'attraction', '黄山', '80元/人（成人），40元/人（学生/老人）', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1396, '徽商故里（屯溪老街店）', '黄山市屯溪区老街248号', '徽商故里是黄山最著名的徽菜餐厅，以正宗徽州菜为主，臭鳜鱼是徽菜的代表作，闻起来臭，吃起来香，肉质鲜嫩，是到黄山必尝的特色美食。', 'restaurant', '黄山', '80-150元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1397, '老街第一楼（屯溪老街店）', '黄山市屯溪区老街168号', '老街第一楼位于屯溪老街内，是黄山最有名的徽菜餐厅之一，以徽州传统菜肴为主，毛豆腐是必尝的特色小吃，外焦里嫩，鲜香味美。', 'restaurant', '黄山', '60-120元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1398, '黄山特色小吃（屯溪老街聚集区）', '黄山市屯溪区老街（多家小吃店）', '屯溪老街是黄山最著名的小吃聚集区，汇聚了黄山各种特色小吃和徽州美食，是品尝黄山特色小吃、体验徽州饮食文化的绝佳去处。', 'restaurant', '黄山', '20-50元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1399, '徽州府衙（歙县徽州古城内）', '黄山市歙县徽州古城内', '徽州府衙是歙县最有名的徽菜餐厅，以徽州传统宴席菜为主，做工精细，口味醇厚，是体验徽州官府菜、了解徽州饮食文化的绝佳去处。', 'restaurant', '黄山', '100-180元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1400, '黟县宏村农家乐（宏村内多家）', '黄山市黟县宏村内（多家农家乐）', '宏村内有大量的农家乐餐厅，以徽州家常菜和农家菜为主，食材新鲜，口味地道，是体验徽州乡村美食、感受古村落慢生活的绝佳去处。', 'restaurant', '黄山', '50-100元', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1401, '黄山悦榕庄酒店', '黄山市黄山区汤口镇寨西村', '超五星级豪华度假酒店，位于黄山风景区脚下，环境清幽，设施豪华，服务一流，是商务出行和高端旅游的理想选择。', 'hotel', '黄山', '1500-3500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1402, '黄山温泉度假酒店', '黄山市黄山区汤口镇温泉度假区内', '五星级温泉度假酒店，位于黄山风景区脚下，拥有丰富的温泉资源，环境优美，是休闲度假、泡温泉的理想选择。', 'hotel', '黄山', '800-2000元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1403, '如家酒店（黄山屯溪老街店）', '黄山市屯溪区老街入口处', '经济型连锁酒店，位于屯溪老街附近，交通便利，房间干净整洁，性价比高，适合预算有限的游客。', 'hotel', '黄山', '180-350元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1404, '宏村和西递古村落民宿', '黄山市黟县宏村、西递村内（多家民宿）', '古色古香的徽派民宿，位于宏村和西递古村落内，建筑风格古朴典雅，充满徽州韵味，是体验徽州文化、感受古村落慢生活的理想住宿选择。', 'hotel', '黄山', '200-600元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());
INSERT INTO place (id, name, address, description, type, city, price, latitude, longitude, source, deleted, create_time, update_time) VALUES (1405, '黄山风景区山上宾馆', '黄山市黄山区黄山风景区内（如：白云宾馆、玉屏楼宾馆等）', '位于黄山风景区内，方便游客观赏日出、云海等景观，是游览黄山期间理想的住宿选择，但需提前预订。', 'hotel', '黄山', '300-1500元/晚', NULL, NULL, 'knowledge', 0, NOW(), NOW());